# KONSOL BAŞLIĞI RASTGELELEŞTİRME (ANTI-PROCESS SCANNER)
# ============================================================
def start_cmd_title_spoofer():
    """CMD Konsol başlığını sürekli 7 haneli rastgele büyük harf ve rakam yapar."""
    def worker():
        while True:
            try:
                rand_title = ''.join(random.choices(string.ascii_uppercase + string.digits, k=7))
                ctypes.windll.kernel32.SetConsoleTitleW(rand_title)
            except Exception:
                pass
            time.sleep(0.15)
    threading.Thread(target=worker, daemon=True).start()

start_cmd_title_spoofer()

# ============================================================
# OTOMATİK ADMİN YETKİ YÜKSELTMESİ (UAC)
# ============================================================
# SendInput API'si admin yetkisi gerektirir (UIPI — User Interface
# Privilege Isolation). Admin değilsek, kendimizi admin olarak
# yeniden başlatıyoruz.
# ============================================================
def is_admin():
    """Mevcut process'in admin yetkisine sahip olup olmadığını kontrol eder."""
    try:
        return ctypes.windll.shell32.IsUserAnAdmin() != 0
    except Exception:
        return False

if os.name == 'nt' and not is_admin():
    print("[!] Admin yetkisi gerekiyor. UAC yetki yükseltmesi başlatılıyor...")
    try:
        abs_script = os.path.abspath(sys.argv[0])
        params = f'"{abs_script}"'
        if len(sys.argv) > 1:
            params += ' ' + ' '.join([f'"{arg}"' for arg in sys.argv[1:]])
            
        ret = ctypes.windll.shell32.ShellExecuteW(
            None,
            "runas",
            sys.executable,
            params,
            os.path.dirname(abs_script),
            1
        )
        if int(ret) > 32:
            print("[+] Yönetici penceresi başlatıldı. Bu pencere kapatılıyor...")
            sys.exit(0)
        else:
            print(f"[!] Yönetici yetkisi alınamadı (Hata Kodu: {ret}). Lütfen UAC uyarısına 'EVET' deyin.")
    except Exception as e:
        print(f"[!] Admin yetki yükseltme başarısız: {e}")
    print("[!] UYARI: Script yönetici olmadan çalışıyor. Oyunlarda tuş vuruşları engellenebilir.")

