# ============================================================
# HID (Human Interface Device) Sürücüleri - SendInput API
# ============================================================
# ULONG_PTR: 32-bit'te 4 byte, 64-bit'te 8 byte (pointer boyutu).
# Yanlış boyut = SendInput sessizce başarısız olur (0 döner).
# ============================================================

# ULONG_PTR — pointer boyutunda unsigned integer (HID struct hizalaması için kritik)
ULONG_PTR = ctypes.c_uint64 if ctypes.sizeof(ctypes.c_void_p) == 8 else ctypes.c_uint32

# INPUT yapı tipleri
INPUT_MOUSE = 0
INPUT_KEYBOARD = 1
INPUT_HARDWARE = 2

# Mouse event sabitleri
MOUSEEVENTF_MOVE       = 0x0001
MOUSEEVENTF_LEFTDOWN   = 0x0002
MOUSEEVENTF_LEFTUP     = 0x0004
MOUSEEVENTF_RIGHTDOWN  = 0x0008
MOUSEEVENTF_RIGHTUP    = 0x0010
MOUSEEVENTF_ABSOLUTE   = 0x8000

# Keyboard event sabitleri
KEYEVENTF_KEYDOWN      = 0x0000
KEYEVENTF_KEYUP        = 0x0002
KEYEVENTF_SCANCODE     = 0x0008  # Hardware scan code kullan (KRITIK!)

# ============================================================
# Scan Code Tablosu — VK'dan hardware scan code'a dönüşüm
# ============================================================
# Vanguard, VK tabanlı simüle klavye girişlerini engelleyebilir
# ama HARDWARE SCAN CODE tabanlı girişleri genellikle geçirir.
# MapVirtualKeyW(vk, MAPVK_VK_TO_VSC) kullanarak dönüştürüyoruz.
# ============================================================
MAPVK_VK_TO_VSC = 0

class MOUSEINPUT(ctypes.Structure):
    """HID Mouse giriş yapısı — Windows MOUSEINPUT ile birebir uyumlu."""
    _fields_ = [
        ("dx", wintypes.LONG),
        ("dy", wintypes.LONG),
        ("mouseData", wintypes.DWORD),
        ("dwFlags", wintypes.DWORD),
        ("time", wintypes.DWORD),
        ("dwExtraInfo", ULONG_PTR),
    ]

class KEYBDINPUT(ctypes.Structure):
    """HID Klavye giriş yapısı."""
    _fields_ = [
        ("wVk", wintypes.WORD),
        ("wScan", wintypes.WORD),
        ("dwFlags", wintypes.DWORD),
        ("time", wintypes.DWORD),
        ("dwExtraInfo", ULONG_PTR),
    ]

class HARDWAREINPUT(ctypes.Structure):
    """HID Donanım giriş yapısı."""
    _fields_ = [
        ("uMsg", wintypes.DWORD),
        ("wParamL", wintypes.WORD),
        ("wParamH", wintypes.WORD),
    ]

class _INPUT_UNION(ctypes.Union):
    """INPUT yapısı için union (mouse/keyboard/hardware)."""
    _fields_ = [
        ("mi", MOUSEINPUT),
        ("ki", KEYBDINPUT),
        ("hi", HARDWAREINPUT),
    ]

class INPUT(ctypes.Structure):
    """Windows SendInput API için ana INPUT yapısı."""
    _fields_ = [
        ("type", wintypes.DWORD),
        ("ii", _INPUT_UNION),
    ]

