import atexit

# Set Windows timer resolution to 1ms for ultra-low latency sleeping and threading
try:
    ctypes.windll.winmm.timeBeginPeriod(1)
except Exception:
    pass

# GDI Cache variables for screen capture optimization
cached_hdc_screen = None
cached_hdc_mem = None
cached_hbm = None
cached_old_bm = None
cached_w = 0
cached_h = 0

def cleanup_gdi():
    global cached_hdc_screen, cached_hdc_mem, cached_hbm, cached_old_bm, cached_w, cached_h
    try:
        if cached_hdc_mem and cached_old_bm:
            _SelectObject(cached_hdc_mem, cached_old_bm)
        if cached_hbm:
            _DeleteObject(cached_hbm)
        if cached_hdc_mem:
            _DeleteDC(cached_hdc_mem)
        if cached_hdc_screen:
            _ReleaseDC(None, cached_hdc_screen)
    except Exception:
        pass
    cached_hdc_screen = None
    cached_hdc_mem = None
    cached_hbm = None
    cached_old_bm = None
    cached_w = 0
    cached_h = 0

atexit.register(cleanup_gdi)

def is_key_pressed(vk_code):
    """Tuşun basılı olup olmadığını kontrol eder."""
    return (_GetAsyncKeyState(vk_code) & 0x8000) != 0

def find_valorant_process():
    """VALORANT sürecini ve PID'sini kontrol eder."""
    try:
        output = subprocess.check_output('tasklist /FI "IMAGENAME eq VALORANT-Win64-Shipping.exe" /FO CSV', shell=True).decode('utf-8', errors='ignore')
        lines = [line for line in output.splitlines() if "VALORANT-Win64-Shipping.exe" in line]
        if lines:
            parts = lines[0].split(',')
            pid = parts[1].strip('"')
            return int(pid)
    except Exception:
        pass
    
    try:
        output = subprocess.check_output('tasklist /FI "IMAGENAME eq VALORANT.exe" /FO CSV', shell=True).decode('utf-8', errors='ignore')
        lines = [line for line in output.splitlines() if "VALORANT.exe" in line]
        if lines:
            parts = lines[0].split(',')
            pid = parts[1].strip('"')
            return int(pid)
    except Exception:
        pass

    return None

