def get_rainbow_color():
    global rainbow_hue
    rainbow_hue = (rainbow_hue + 0.02) % 1.0
    import colorsys
    r, g, b = colorsys.hsv_to_rgb(rainbow_hue, 1.0, 1.0)
    return f"#{int(r*255):02x}{int(g*255):02x}{int(b*255):02x}"

def update_watermark_ui():
    if not fov_canvas:
        return
    fov_canvas.delete("watermark")
    if watermark_on:
        wm_text = "⚡ OBEZP1C VIP"
        color = get_rainbow_color() if watermark_rainbow else "#00F0FF"
        
        fov_canvas.create_text(22, 22, text=wm_text, font=("Impact", 15), fill="#000000", anchor="nw", tags="watermark")
        fov_canvas.create_text(20, 20, text=wm_text, font=("Impact", 15), fill=color, anchor="nw", tags="watermark")

def update_center_dot_ui():
    if not fov_canvas:
        return
    fov_canvas.delete("center_dot")
    if center_dot_on:
        sw = fov_canvas.winfo_width()
        sh = fov_canvas.winfo_height()
        if (sw <= 1 or sh <= 1) and overlay_root:
            sw = overlay_root.winfo_screenwidth()
            sh = overlay_root.winfo_screenheight()
        cx, cy = sw // 2, sh // 2
        r = 2
        fov_canvas.create_oval(cx - r - 1, cy - r - 1, cx + r + 1, cy + r + 1, outline="#000000", width=1, tags="center_dot")
        fov_canvas.create_oval(cx - r, cy - r, cx + r, cy + r, fill="#00FF66", outline="", tags="center_dot")

def watermark_animation_loop():
    if overlay_root:
        try:
            update_watermark_ui()
            update_center_dot_ui()
        except Exception:
            pass
        overlay_root.after(50, watermark_animation_loop)

