VK_SPACE = 0x20

def send_space_jump():
    """Space tuşuna hızlı bas-bırak gönderir."""
    sc = ctypes.windll.user32.MapVirtualKeyW(VK_SPACE, 0)
    inp_down = INPUT()
    inp_down.type = INPUT_KEYBOARD
    inp_down.ii.ki.wVk = VK_SPACE
    inp_down.ii.ki.wScan = sc
    inp_down.ii.ki.dwFlags = 0
    _SendInput(1, ctypes.addressof(inp_down), ctypes.sizeof(INPUT))
    time.sleep(0.01)
    inp_up = INPUT()
    inp_up.type = INPUT_KEYBOARD
    inp_up.ii.ki.wVk = VK_SPACE
    inp_up.ii.ki.wScan = sc
    inp_up.ii.ki.dwFlags = KEYEVENTF_KEYUP
    _SendInput(1, ctypes.addressof(inp_up), ctypes.sizeof(INPUT))

def bhop_thread():
    """Bhop aktifken Space tuşuna basılı tutulduğunda sürekli zıplama sinyali gönderir."""
    while True:
        if bhop_on:
            if is_key_pressed(VK_SPACE):
                send_space_jump()
                time.sleep(0.030)
            else:
                time.sleep(0.01)
        else:
            time.sleep(0.05)

threading.Thread(target=bhop_thread, daemon=True).start()

def autopistol_thread():
    """AutoPistol aktifken Sol Fare Tıklamasına basılı tutulduğunda sürekli seri ateş eder."""
    while True:
        if autopistol_on:
            if is_key_pressed(0x01): # VK_LBUTTON
                trigger_click()
                time.sleep(0.12) # Seri tabanca ateşleme hızı
            else:
                time.sleep(0.01)
        else:
            time.sleep(0.05)

threading.Thread(target=autopistol_thread, daemon=True).start()

def anti_afk_thread():
    """Anti-AFK aktifken oyuncunun oyundan atılmaması için belirli aralıklarla mikro hareket tuşu gönderir."""
    while True:
        if anti_afk_on:
            time.sleep(12.0)
            if anti_afk_on:
                try:
                    sc_a = ctypes.windll.user32.MapVirtualKeyW(0x41, 0)
                    sc_d = ctypes.windll.user32.MapVirtualKeyW(0x44, 0)
                    
                    inp = INPUT()
                    inp.type = INPUT_KEYBOARD
                    inp.ii.ki.wVk = 0x41
                    inp.ii.ki.wScan = sc_a
                    inp.ii.ki.dwFlags = 0
                    _SendInput(1, ctypes.addressof(inp), ctypes.sizeof(INPUT))
                    time.sleep(0.05)
                    inp.ii.ki.dwFlags = KEYEVENTF_KEYUP
                    _SendInput(1, ctypes.addressof(inp), ctypes.sizeof(INPUT))
                    
                    time.sleep(0.1)
                    
                    inp.ii.ki.wVk = 0x44
                    inp.ii.ki.wScan = sc_d
                    inp.ii.ki.dwFlags = 0
                    _SendInput(1, ctypes.addressof(inp), ctypes.sizeof(INPUT))
                    time.sleep(0.05)
                    inp.ii.ki.dwFlags = KEYEVENTF_KEYUP
                    _SendInput(1, ctypes.addressof(inp), ctypes.sizeof(INPUT))
                except Exception:
                    pass
        else:
            time.sleep(0.5)

threading.Thread(target=anti_afk_thread, daemon=True).start()

def recoil_assist_thread():
    """Recoil Assist aktifken sol fare tıklamasına basılı tutulduğunda mikro spreyleme geri tepme kontrolü uygular."""
    while True:
        if recoil_assist_on:
            if is_key_pressed(0x01): # VK_LBUTTON
                try:
                    extra = _GetMessageExtraInfo()
                    _mouse_event(MOUSEEVENTF_MOVE, 0, 2, 0, extra)
                except Exception:
                    pass
                time.sleep(0.035)
            else:
                time.sleep(0.01)
        else:
            time.sleep(0.05)

threading.Thread(target=recoil_assist_thread, daemon=True).start()



def discord_rpc_thread():
    """Arka planda Discord Rich Presence (Oynuyor) durumunu günceller."""
    global discord_rpc_on, discord_client_id
    rpc = None
    start_time = time.time()
    
    while True:
        if discord_rpc_on:
            if rpc is None:
                try:
                    from pypresence import Presence
                    rpc = Presence(discord_client_id)
                    rpc.connect()
                except Exception:
                    rpc = None
            
            if rpc:
                try:
                    rpc.update(
                        details="OBEZP1C VIP",
                        large_image="jett",
                        large_text="Jett",
                        start=int(start_time)
                    )
                except Exception:
                    rpc = None
        else:
            if rpc:
                try:
                    rpc.close()
                except Exception:
                    pass
                rpc = None
        
        time.sleep(15)

threading.Thread(target=discord_rpc_thread, daemon=True).start()

