LOCK_IN_COORD_1920 = (960, 750)  # KİLİTLE butonu (tam ortası)

def click_at_screen_pos(x, y):
    """Belirtilen ekran koordinatına sol tık yapar (Agent Select / Instalock için).
    Valorant'ın tıklamayı algılaması için basılı tutma süresi (hold time) ve çoklu API desteği içerir.
    """
    try:
        ix, iy = int(x), int(y)
        ctypes.windll.user32.SetCursorPos(ix, iy)
        time.sleep(0.002)
        extra = _GetMessageExtraInfo()
        
        # 1. mouse_event
        _mouse_event(MOUSEEVENTF_LEFTDOWN, 0, 0, 0, extra)
        
        # 2. PostMessage (Valorant penceresi varsa doğrudan mesaja da ilet)
        vhwnd = _find_valorant_hwnd()
        if vhwnd:
            lp = ((iy) << 16) | ((ix) & 0xFFFF)
            _PostMessageW(vhwnd, 0x0201, 0x0001, lp)  # WM_LBUTTONDOWN
            
        time.sleep(0.012)  # Oyunun tıklamayı yakalaması için kritik hold süresi
        
        _mouse_event(MOUSEEVENTF_LEFTUP, 0, 0, 0, extra)
        if vhwnd:
            lp = ((iy) << 16) | ((ix) & 0xFFFF)
            _PostMessageW(vhwnd, 0x0202, 0, lp)       # WM_LBUTTONUP
    except Exception:
        pass

def instalock_thread():
    """Instalock & Show Agent döngüsü - arka planda sürekli çalışır."""
    global instalock_on, show_agent_on
    while True:
        time.sleep(0.005)
        if not instalock_on and not show_agent_on:
            continue
            
        sw = _GetSystemMetrics(0)
        sh = _GetSystemMetrics(1)
        
        agent_name = agent_options[agent_index]
        ref_x, ref_y = AGENT_COORDS_1920.get(agent_name, (190, 415))  # Varsayılan JETT
        
        target_x = (ref_x / 1920.0) * sw
        target_y = (ref_y / 1080.0) * sh
        
        # Karakter seç (Show Agent & Instalock için ortak)
        click_at_screen_pos(target_x, target_y)
        
        # Sadece Instalock aktifse kilitle butonuna tıkla
        if instalock_on:
            lock_x = (LOCK_IN_COORD_1920[0] / 1920.0) * sw
            lock_y = (LOCK_IN_COORD_1920[1] / 1080.0) * sh
            click_at_screen_pos(lock_x, lock_y)
            time.sleep(0.01)
        else:
            # Show Agent modunda ajana sürekli tıklama döngüsü
            time.sleep(0.03)

