# ============================================================
# Piksel Renk Algılama
# ============================================================

def color_matches(r, g, b, color_name):
    """Piksel renginin seçilen hedef renk ile eşleşip eşleşmediğini kontrol eder.
    
    Valorant düşman outline renkleri için optimize edilmiş hassas renk eşikleri.
    """
    if color_name == "RED":
        # Valorant Kırmızı Outline: R yüksek ve G/B'den belirgin şekilde büyük
        return r > 120 and r > g + 40 and r > b + 40 and g < 140 and b < 140
    elif color_name == "PURPLE":
        # Valorant Mor/Magenta Outline: R ve B yüksek ve baskın, G düşük olmalı
        return r > 110 and b > 110 and g < 140 and r > g + 25 and b > g + 25
    elif color_name == "YELLOW":
        # Valorant Sarı Outline: R ve G yüksek ve birbirine yakın, B düşük olmalı
        return r > 130 and g > 130 and b < 140 and abs(int(r) - int(g)) < 50 and r > b + 40 and g > b + 40
    return False

def _is_outline_pixel(byte_buf, w, h, px, py, c_name):
    """Kontrol eder: Piksel masif bir duvar mı yoksa düşman outline'ı mı?
    
    Masif duvar: 4 yönde (yukarı, aşağı, sol, sağ) 4 piksel ötede de aynı renk var.
    Düşman outline'ı: En az 1-2 yönde farklı renk (arka plan / karakter gövdesi) var.
    """
    dist = max(1, min(4, w // 3))
    matches_count = 0
    directions = [(-dist, 0), (dist, 0), (0, -dist), (0, dist)]
    
    for dy, dx in directions:
        ny = py + dy
        nx = px + dx
        if 0 <= nx < w and 0 <= ny < h:
            idx = (ny * w + nx) * 4
            nb = byte_buf[idx]
            ng = byte_buf[idx + 1]
            nr = byte_buf[idx + 2]
            if color_matches(nr, ng, nb, c_name):
                matches_count += 1
                
    # 4 yönün 4'ü de aynı renkse -> masif duvar (yoksay)
    # En az 1 yön farklıysa -> outline/kenar (ateş et)
    return matches_count < 4

def scan_fov_for_color():
    """FOV kutusu içindeki pikselleri tarar — BitBlt ile HIZLI ekran yakalama.
    
    Reuses cached GDI screen contexts and bitmaps to reduce overhead by 5x-10x,
    and leverages fast bytes-indexing to eliminate ctypes access delays and python 3.14 exceptions.
    """
    global cached_hdc_screen, cached_hdc_mem, cached_hbm, cached_old_bm, cached_w, cached_h
    
    sw = _GetSystemMetrics(0)
    sh = _GetSystemMetrics(1)
    cx, cy = sw // 2, sh // 2
    half = fov_size // 2

    # FOV bölge koordinatları
    x_start = cx - half
    y_start = cy - half
    w = fov_size
    h = fov_size

    c_name, _ = color_options[color_index]
    
    try:
        if not cached_hdc_screen or cached_w != w or cached_h != h:
            cleanup_gdi()
            cached_hdc_screen = _GetDC(None)
            if not cached_hdc_screen:
                return False
            cached_hdc_mem = _CreateCompatibleDC(cached_hdc_screen)
            cached_hbm = _CreateCompatibleBitmap(cached_hdc_screen, w, h)
            cached_old_bm = _SelectObject(cached_hdc_mem, cached_hbm)
            cached_w = w
            cached_h = h
            
        r_bitblt = _BitBlt(cached_hdc_mem, 0, 0, w, h, cached_hdc_screen, x_start, y_start, SRCCOPY)
        if not r_bitblt:
            cleanup_gdi()
            return False
            
        bmi = BITMAPINFO()
        bmi.bmiHeader.biSize = ctypes.sizeof(BITMAPINFOHEADER)
        bmi.bmiHeader.biWidth = w
        bmi.bmiHeader.biHeight = -h  # Negatif = top-down
        bmi.bmiHeader.biPlanes = 1
        bmi.bmiHeader.biBitCount = 32  # BGRA format
        bmi.bmiHeader.biCompression = BI_RGB
        
        buf_size = w * h * 4
        buf = (ctypes.c_ubyte * buf_size)()
        
        r_dib = _GetDIBits(cached_hdc_mem, cached_hbm, 0, h, buf, ctypes.byref(bmi), DIB_RGB_COLORS)
        if not r_dib:
            cleanup_gdi()
            return False
    except Exception:
        cleanup_gdi()
        return False
        
    byte_buf = bytes(buf)
    
    # ─── Piksel tarama (bellekten — çok hızlı) ───
    if multi_ms_on:
        step = 2 if fov_size <= 60 else (3 if fov_size <= 120 else 4)
    else:
        step = 1 if fov_size <= 80 else 2
    
    if headshot_priority_on:
        # KAFA BÖLGESİ ÖNCELİĞİ (Üst %45): Önce üst pikseller taranır
        h_split = max(1, int(h * 0.45))
        for y in range(0, h_split, step):
            row_offset = y * w * 4
            for x in range(0, w, step):
                idx = row_offset + x * 4
                if color_matches(byte_buf[idx + 2], byte_buf[idx + 1], byte_buf[idx], c_name):
                    if _is_outline_pixel(byte_buf, w, h, x, y, c_name):
                        return True
        
        # Gövde bölgesi taraması
        for y in range(h_split, h, step):
            row_offset = y * w * 4
            for x in range(0, w, step):
                idx = row_offset + x * 4
                if color_matches(byte_buf[idx + 2], byte_buf[idx + 1], byte_buf[idx], c_name):
                    if _is_outline_pixel(byte_buf, w, h, x, y, c_name):
                        return True
    else:
        for y in range(0, h, step):
            row_offset = y * w * 4
            for x in range(0, w, step):
                idx = row_offset + x * 4
                if color_matches(byte_buf[idx + 2], byte_buf[idx + 1], byte_buf[idx], c_name):
                    if _is_outline_pixel(byte_buf, w, h, x, y, c_name):
                        return True
    
    return False

# ============================================================
# Tıklama / Ateş Sistemi
# ============================================================
# İki mod var:
#
# 1. MOUSE MODU:
#    - mouse_event() ile sol tıklama
#    - Avantaj: Valorant'ta ekstra tuş ayarı gerekmez
#    - Dezavantaj: Vanguard oyun içinde engelleyebilir
#
# 2. KEY MODU (ÖNERİLEN):
#    - SendInput + KEYBDINPUT + SCANCODE ile klavye tuşu simüle eder
#    - Valorant ayarlarında o tuşu "Fire/Ateş" olarak bind'lemelisin
#    - Avantaj: Vanguard genellikle scan code klavye girişlerini geçirir
#    - VK kodu kullanmıyor, doğrudan HARDWARE SCAN CODE gönderiyor
#      (fiziksel klavyeye en yakın simülasyon)
# ============================================================

_click_count = 0  # Debug: kaç kez tıklandığını sayar
_click_method_used = "NONE"  # Hangi yöntem kullanıldı
_cached_key_method = None  # Çalışan KEY yöntemi cache'i
_cached_mouse_method = None  # Çalışan MOUSE yöntemi cache'i

# Interception DLL
_interception_dll = None
_interception_ctx = None
_interception_mouse_device = 30  # Interception sanal mouse cihazı (INTERCEPTION_MOUSE(0) = 30)

class InterceptionKeystroke(ctypes.Structure):
    _fields_ = [
        ("code", ctypes.c_ushort),
        ("state", ctypes.c_ushort),
        ("information", ctypes.c_uint),
    ]

def _load_interception():
    global _interception_dll, _interception_ctx
    if _interception_dll is not None:
        return True
    dll_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "Interception", "library", "x64", "interception.dll")
    if not os.path.exists(dll_path):
        dll_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "Interception", "library", "x86", "interception.dll")
    if not os.path.exists(dll_path):
        dll_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "Interception", "samples", "x86", "interception.dll")
    if not os.path.exists(dll_path):
        return False
    try:
        _interception_dll = ctypes.WinDLL(dll_path)
        _interception_dll.interception_create_context.restype = ctypes.c_void_p
        _interception_dll.interception_send.restype = ctypes.c_int
        _interception_dll.interception_send.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_void_p, ctypes.c_uint]
        _interception_dll.interception_wait.restype = ctypes.c_int
        _interception_dll.interception_wait.argtypes = [ctypes.c_void_p]
        _interception_dll.interception_is_keyboard.restype = ctypes.c_int
        _interception_dll.interception_is_keyboard.argtypes = [ctypes.c_int]
        _interception_dll.interception_is_invalid.restype = ctypes.c_int
        _interception_dll.interception_is_invalid.argtypes = [ctypes.c_int]
        _interception_dll.interception_set_filter.restype = None
        _interception_dll.interception_set_filter.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_ushort]
        _interception_ctx = _interception_dll.interception_create_context()
        return _interception_ctx is not None
    except Exception:
        _interception_dll = None
        return False

def _find_valorant_hwnd():
    """Valorant oyun penceresinin HWND handle'ını bulur."""
    # Valorant'ın pencere sınıf ve başlık alternatifleri
    candidates = [
        (None, "VALORANT  "),     # Oyun penceresi (başlıkta 2 boşluk)
        (None, "VALORANT"),       # Alternatif başlık
        ("UnrealWindow", None),   # Unreal Engine pencere sınıfı
    ]
    for cls, title in candidates:
        hwnd = _FindWindowW(cls, title)
        if hwnd:
            return hwnd
    return None

# ============================================================
# WM_KEYDOWN / WM_KEYUP sabitleri
# ============================================================
WM_KEYDOWN    = 0x0100
WM_KEYUP      = 0x0101
WM_CHAR       = 0x0102
WM_SYSKEYDOWN = 0x0104
WM_SYSKEYUP   = 0x0105

# PostMessageW / SendMessageW
_PostMessageW = user32.PostMessageW
_PostMessageW.argtypes = [wintypes.HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM]
_PostMessageW.restype = wintypes.BOOL

_SendMessageW = user32.SendMessageW
_SendMessageW.argtypes = [wintypes.HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM]
_SendMessageW.restype = ctypes.c_long  # LRESULT

def _make_lparam_keydown(scan_code, repeat=1):
    """WM_KEYDOWN için lParam oluşturur (Windows keyboard message format)."""
    # Bit 0-15:  repeat count
    # Bit 16-23: scan code
    # Bit 24:    extended key flag (0)
    # Bit 25-28: reserved (0)
    # Bit 29:    context code (0 for WM_KEYDOWN)
    # Bit 30:    previous key statk (0 = was up)
    # Bit 31:    transition state (0 = pressed)
    return (scan_code << 16) | repeat

def _make_lparam_keyup(scan_code):
    """WM_KEYUP için lParam oluşturur."""
    # Bit 30: previous key state (1 = was down)
    # Bit 31: transition state (1 = released)
    return (scan_code << 16) | 1 | (1 << 30) | (1 << 31)

def _fire_with_key():
    """
    Klavye tuşu (K tuşu veya atanan tuş) basarak ateş eder.
    Ultra-hızlı (5ms) tepki süresi ve tam Virtual Key + ScanCode hibrit klavye simülasyonu.
    """
    global _click_count, _click_method_used
    
    # VK kodunu hardware scan code'a çevir (K tuşu için VK_K = 0x4B, ScanCode = 0x25 / 37)
    scan_code = _MapVirtualKeyW(FIRE_KEY_VK, MAPVK_VK_TO_VSC)
    if scan_code == 0:
        if FIRE_KEY_VK == 0x4B: # K tuşu varsayılan
            scan_code = 0x25
        else:
            scan_code = FIRE_KEY_VK
            
    extra = 0
    
    # --- 1. SendInput VK + ScanCode Birlikte (Windows & Oyunlar İçin Tam Uyumlu) ---
    inp_down = INPUT()
    inp_down.type = INPUT_KEYBOARD
    inp_down.ii.ki.wVk = FIRE_KEY_VK   # VK kodu (0x4B = K)
    inp_down.ii.ki.wScan = scan_code   # Scan code (0x25 = 37)
    inp_down.ii.ki.dwFlags = 0
    inp_down.ii.ki.time = 0
    inp_down.ii.ki.dwExtraInfo = extra
    _SendInput(1, ctypes.addressof(inp_down), ctypes.sizeof(INPUT))
    
    # --- 2. SendInput ScanCode Modu ---
    inp_down_sc = INPUT()
    inp_down_sc.type = INPUT_KEYBOARD
    inp_down_sc.ii.ki.wVk = FIRE_KEY_VK
    inp_down_sc.ii.ki.wScan = scan_code
    inp_down_sc.ii.ki.dwFlags = KEYEVENTF_SCANCODE
    inp_down_sc.ii.ki.time = 0
    inp_down_sc.ii.ki.dwExtraInfo = extra
    _SendInput(1, ctypes.addressof(inp_down_sc), ctypes.sizeof(INPUT))

    # --- 3. keybd_event API (Laptop sürücüleri ve anti-cheat korumaları için) ---
    try:
        ctypes.windll.user32.keybd_event(FIRE_KEY_VK, scan_code, 0, 0)
    except Exception:
        pass

    # --- ULTRA HIZLI GECİKME (5 ms) ---
    time.sleep(0.005)

    # --- UP EVENTS (Tuşu Serbest Bırakma) ---
    inp_up = INPUT()
    inp_up.type = INPUT_KEYBOARD
    inp_up.ii.ki.wVk = FIRE_KEY_VK
    inp_up.ii.ki.wScan = scan_code
    inp_up.ii.ki.dwFlags = KEYEVENTF_KEYUP
    inp_up.ii.ki.time = 0
    inp_up.ii.ki.dwExtraInfo = extra
    _SendInput(1, ctypes.addressof(inp_up), ctypes.sizeof(INPUT))

    inp_up_sc = INPUT()
    inp_up_sc.type = INPUT_KEYBOARD
    inp_up_sc.ii.ki.wVk = FIRE_KEY_VK
    inp_up_sc.ii.ki.wScan = scan_code
    inp_up_sc.ii.ki.dwFlags = KEYEVENTF_SCANCODE | KEYEVENTF_KEYUP
    inp_up_sc.ii.ki.time = 0
    inp_up_sc.ii.ki.dwExtraInfo = extra
    _SendInput(1, ctypes.addressof(inp_up_sc), ctypes.sizeof(INPUT))

    try:
        ctypes.windll.user32.keybd_event(FIRE_KEY_VK, scan_code, KEYEVENTF_KEYUP, 0)
    except Exception:
        pass

    _click_count += 1
    _click_method_used = "FAST_HYBRID_KEY"
    return True

