def _key_method_array_sc(scan_code, extra):
    """Array-based SendInput (DOWN+UP ayrı ayrı gecikmeli)."""
    inp_down = INPUT()
    inp_down.type = INPUT_KEYBOARD
    inp_down.ii.ki.wVk = 0
    inp_down.ii.ki.wScan = scan_code
    inp_down.ii.ki.dwFlags = KEYEVENTF_SCANCODE
    inp_down.ii.ki.time = 0
    inp_down.ii.ki.dwExtraInfo = extra
    r1 = _SendInput(1, ctypes.addressof(inp_down), ctypes.sizeof(INPUT))
    
    time.sleep(0.02)
    
    inp_up = INPUT()
    inp_up.type = INPUT_KEYBOARD
    inp_up.ii.ki.wVk = 0
    inp_up.ii.ki.wScan = scan_code
    inp_up.ii.ki.dwFlags = KEYEVENTF_SCANCODE | KEYEVENTF_KEYUP
    inp_up.ii.ki.time = 0
    inp_up.ii.ki.dwExtraInfo = extra
    r2 = _SendInput(1, ctypes.addressof(inp_up), ctypes.sizeof(INPUT))
    return r1 > 0 and r2 > 0

