def _key_method_postmsg(scan_code, extra):
    """PostMessage — Valorant penceresine doğrudan mesaj."""
    vhwnd = _find_valorant_hwnd()
    if not vhwnd:
        return False
    lp_down = _make_lparam_keydown(scan_code)
    lp_up = _make_lparam_keyup(scan_code)
    r1 = _PostMessageW(vhwnd, WM_KEYDOWN, FIRE_KEY_VK, lp_down)
    time.sleep(0.001 if multi_ms_on else 0.005)
    r2 = _PostMessageW(vhwnd, WM_KEYUP, FIRE_KEY_VK, lp_up)
    return bool(r1 and r2)

def _key_method_sendmsg(scan_code, extra):
    """SendMessage — Senkron pencere mesajı."""
    vhwnd = _find_valorant_hwnd()
    if not vhwnd:
        return False
    lp_down = _make_lparam_keydown(scan_code)
    lp_up = _make_lparam_keyup(scan_code)
    _SendMessageW(vhwnd, WM_KEYDOWN, FIRE_KEY_VK, lp_down)
    time.sleep(0.001 if multi_ms_on else 0.005)
    _SendMessageW(vhwnd, WM_KEYUP, FIRE_KEY_VK, lp_up)
    return True

