def _mouse_method_sendinput(extra):
    """SendInput + MOUSEINPUT."""
    inp_down = INPUT()
    inp_down.type = INPUT_MOUSE
    inp_down.ii.mi.dwFlags = MOUSEEVENTF_LEFTDOWN
    inp_down.ii.mi.dwExtraInfo = extra
    r1 = _SendInput(1, ctypes.addressof(inp_down), ctypes.sizeof(INPUT))
    
    inp_up = INPUT()
    inp_up.type = INPUT_MOUSE
    inp_up.ii.mi.dwFlags = MOUSEEVENTF_LEFTUP
    inp_up.ii.mi.dwExtraInfo = extra
    r2 = _SendInput(1, ctypes.addressof(inp_up), ctypes.sizeof(INPUT))
    return r1 > 0 and r2 > 0

def _mouse_method_postmsg(extra):
    """PostMessage WM_LBUTTONDOWN/UP."""
    vhwnd = _find_valorant_hwnd()
    if not vhwnd:
        return False
    sw = _GetSystemMetrics(0)
    sh = _GetSystemMetrics(1)
    lp = ((sh // 2) << 16) | ((sw // 2) & 0xFFFF)
    _PostMessageW(vhwnd, 0x0201, 0x0001, lp)  # WM_LBUTTONDOWN
    _PostMessageW(vhwnd, 0x0202, 0, lp)        # WM_LBUTTONUP
    return True

# Logitech G HUB Driver click integration
logitech_dll = None

def init_logitech():
    global logitech_dll
    dll_paths = [
        "lghub_device.dll",
        r"C:\Program Files\LGHUB\lghub_device.dll",
        r"C:\Program Files (x86)\LGHUB\lghub_device.dll",
    ]
    for path in dll_paths:
        if os.path.exists(path):
            try:
                logitech_dll = ctypes.CDLL(path)
                logitech_dll.device_open(1)
                return True
            except Exception:
                pass
    return False

def _fire_with_logitech():
    global logitech_dll, _click_count, _click_method_used
    if logitech_dll is None:
        init_logitech()
    if logitech_dll:
        try:
            logitech_dll.mouse_click(1) # 1 = Left Click
            _click_count += 1
            _click_method_used = "LOGITECH_Driver"
            return True
        except Exception:
            pass
    # Fallback to mouse if G HUB fails
    return _fire_with_mouse()

# Arduino Serial HID click integration
arduino_serial = None

def init_arduino():
    global arduino_serial
    try:
        import serial
    except ImportError:
        return False
    
    # Try common COM ports
    for i in range(1, 21):
        try:
            port = f"COM{i}"
            arduino_serial = serial.Serial(port, 9600, timeout=0.1)
            return True
        except Exception:
            pass
    return False

def _fire_with_arduino():
    global arduino_serial, _click_count, _click_method_used
    if arduino_serial is None:
        init_arduino()
    if arduino_serial:
        try:
            arduino_serial.write(b'1') # Click command
            _click_count += 1
            _click_method_used = "ARDUINO_HID"
            return True
        except Exception:
            arduino_serial = None
    # Fallback to mouse if Arduino fails
    return _fire_with_mouse()

def _fire_with_interception():
    global _click_count, _click_method_used, _interception_dll, _interception_ctx
    if _interception_dll is None:
        if not _load_interception():
            return False
    if _interception_ctx is None:
        return False
    scan_code = _MapVirtualKeyW(FIRE_KEY_VK, MAPVK_VK_TO_VSC)
    if scan_code == 0:
        scan_code = 0x25 if FIRE_KEY_VK == 0x4B else FIRE_KEY_VK
    INTERCEPTION_KEYBOARD_0 = 1
    stroke_down = InterceptionKeystroke()
    stroke_down.code = scan_code
    stroke_down.state = 0x00
    stroke_down.information = 0
    ret = _interception_dll.interception_send(_interception_ctx, INTERCEPTION_KEYBOARD_0, ctypes.byref(stroke_down), 1)
    if ret <= 0:
        ret = _interception_dll.interception_send(_interception_ctx, 2, ctypes.byref(stroke_down), 1)
    time.sleep(0.005)
    stroke_up = InterceptionKeystroke()
    stroke_up.code = scan_code
    stroke_up.state = 0x01
    stroke_up.information = 0
    ret2 = _interception_dll.interception_send(_interception_ctx, INTERCEPTION_KEYBOARD_0, ctypes.byref(stroke_up), 1)
    if ret2 <= 0:
        ret2 = _interception_dll.interception_send(_interception_ctx, 2, ctypes.byref(stroke_up), 1)
    if ret > 0 or ret2 > 0:
        _click_count += 1
        _click_method_used = "INTERCEPTION"
        return True
    return False

def _perform_counter_strafe():
    """Zıt yön tuşuna mikro dokunuş yaparak hareketi zınk diye durdurur (Counter-Strafe)."""
    if not counter_strafe_on:
        return
    try:
        extra = _GetMessageExtraInfo()
        if is_key_pressed(0x41):   # A basılı -> D mikro dokun
            _key_method_array_sc(_MapVirtualKeyW(0x44, MAPVK_VK_TO_VSC), extra)
        elif is_key_pressed(0x44): # D basılı -> A mikro dokun
            _key_method_array_sc(_MapVirtualKeyW(0x41, MAPVK_VK_TO_VSC), extra)
        elif is_key_pressed(0x57): # W basılı -> S mikro dokun
            _key_method_array_sc(_MapVirtualKeyW(0x53, MAPVK_VK_TO_VSC), extra)
        elif is_key_pressed(0x53): # S basılı -> W mikro dokun
            _key_method_array_sc(_MapVirtualKeyW(0x57, MAPVK_VK_TO_VSC), extra)
    except Exception:
        pass

def trigger_click():
    """
    Ateş et — humanizer koruma aktifse veya jitter ayarları seçilmişse insansı tepki süreleri ekler.
    """
    global _click_method_used
    
    _perform_counter_strafe()

    import random
    # Jitter gecikmesi
    jitter_val = 0.0
    if sec_delay_jitter == 1:
        jitter_val = random.uniform(0.001, 0.003)
    elif sec_delay_jitter == 2:
        jitter_val = random.uniform(0.003, 0.008)
    elif sec_delay_jitter == 3:
        jitter_val = random.uniform(0.005, 0.015)
        
    if jitter_val > 0:
        time.sleep(jitter_val)

    if humanizer_on and not multi_ms_on:
        time.sleep(random.uniform(0.002, 0.007))  # Insan kas tepki süresi jütteri (Ultra-Fast Response)
        
    success = _fire_with_interception()
    if not success:
        success = _fire_with_key()
    if not success:
        success = _fire_with_mouse()
    
    if not success:
        _click_method_used = "FAILED"
        print(f"{RED}[!] ATEŞ BAŞARISIZ! Tüm yöntemler denendi.{RESET}")

def trigger_scan_thread():
    """Trigger tarama döngüsü - arka plan thread'i olarak çalışır."""
    global led_triggered, toggle_active, scan_active
    
    prev_bind = False
    last_debug_time = 0
    
    while True:
        # Menü yoksa veya trigger kapalıysa dinlen
        if not overlay_root or not trigger_on:
            led_triggered = False
            scan_active = False
            if overlay_root:
                try:
                    overlay_root.after(0, update_led)
                except Exception:
                    pass
            time.sleep(0.05)
            continue
        
        # Trigger bind tuşu kontrolü
        bind_pressed = is_key_pressed(trigger_bind_vk)
        
        should_scan = False
        
        if trigger_mode == "HOLD":
            should_scan = bind_pressed
        elif trigger_mode == "TOGGLE":
            if bind_pressed and not prev_bind:
                toggle_active = not toggle_active
                state = "AKTİF" if toggle_active else "KAPALI"
                print(f"{CYAN}[TOGGLE] Trigger tarama: {state}{RESET}")
            should_scan = toggle_active
        
        prev_bind = bind_pressed
        
        if should_scan:
            scan_active = True
            found = scan_fov_for_color()
            
            if found:
                led_triggered = True
                if overlay_root:
                    try:
                        overlay_root.after(0, update_led)
                    except Exception:
                        pass
                
                # ATEŞ ET!
                trigger_click()
                
                # Debug: Her 2 saniyede bir sayaç yazdır
                now = time.time()
                if now - last_debug_time > 2.0:
                    print(f"{GREEN}[FIRE] Toplam: {_click_count} | Yöntem: {_click_method_used} | Mod: {fire_mode}{RESET}")
                    last_debug_time = now
                
                # Ateş gecikmesi / hızı ayarı (ms -> saniye dönüşümü)
                if fire_delay > 0 and not multi_ms_on:
                    time.sleep(fire_delay / 1000.0)
            else:
                led_triggered = False
                if overlay_root:
                    try:
                        overlay_root.after(0, update_led)
                    except Exception:
                        pass
            # Aktif tarama: sıfır gecikme / veya tarama jitteri ekle, CPU'ya micro-yield
            if sec_scan_jitter:
                import random
                time.sleep(random.uniform(0.0005, 0.002))
        else:
            scan_active = False
            if led_triggered:
                led_triggered = False
                if overlay_root:
                    try:
                        overlay_root.after(0, update_led)
                    except Exception:
                        pass
            time.sleep(0.005)  # Pasif: 5ms

# ────────────────────────────────────────────────────────────
# AIMBOT — HEDEF BULMA, SMOOTH MOUSE HAREKETİ VE ATEŞ
# ────────────────────────────────────────────────────────────
_aim_gdi_lock = threading.Lock()
_last_aim_target = None  # Debug: en son bulunan hedef koordinatı
_aim_cache_dc = None
_aim_cache_mem = None
_aim_cache_bm = None
_aim_cache_old = None
_aim_cache_w = 0
_aim_cache_h = 0

def _aim_gdi_cleanup():
    global _aim_cache_dc, _aim_cache_mem, _aim_cache_bm, _aim_cache_old, _aim_cache_w, _aim_cache_h
    try:
        if _aim_cache_mem and _aim_cache_old:
            _SelectObject(_aim_cache_mem, _aim_cache_old)
        if _aim_cache_bm:
            _DeleteObject(_aim_cache_bm)
        if _aim_cache_mem:
            _DeleteDC(_aim_cache_mem)
        if _aim_cache_dc:
            _ReleaseDC(None, _aim_cache_dc)
    except Exception:
        pass
    _aim_cache_dc = None
    _aim_cache_mem = None
    _aim_cache_bm = None
    _aim_cache_old = None
    _aim_cache_w = 0
    _aim_cache_h = 0

def _aimbot_find_target():
    """FOV içinde hedef rengi tara, crosshair'e en yakın hedef pikselin ekran koordinatını döndür.
    Thread-safe cached GDI, trigger scan ile aynı yöntem. Renk trigger'dan (color_index) çekilir."""
    global _aim_cache_dc, _aim_cache_mem, _aim_cache_bm, _aim_cache_old, _aim_cache_w, _aim_cache_h
    c_name = color_options[color_index][0]
    with _aim_gdi_lock:
        try:
            sw = _GetSystemMetrics(0)
            sh = _GetSystemMetrics(1)
            half = aim_fov_size // 2
            cx, cy = sw // 2, sh // 2
            x_start = cx - half
            y_start = cy - half
            w = aim_fov_size
            h = aim_fov_size

            if not _aim_cache_dc or _aim_cache_w != w or _aim_cache_h != h:
                _aim_gdi_cleanup()
                _aim_cache_dc = _GetDC(None)
                if not _aim_cache_dc:
                    return None
                _aim_cache_mem = _CreateCompatibleDC(_aim_cache_dc)
                _aim_cache_bm = _CreateCompatibleBitmap(_aim_cache_dc, w, h)
                _aim_cache_old = _SelectObject(_aim_cache_mem, _aim_cache_bm)
                _aim_cache_w = w
                _aim_cache_h = h

            if not _BitBlt(_aim_cache_mem, 0, 0, w, h, _aim_cache_dc, x_start, y_start, SRCCOPY):
                return None

            bmi = BITMAPINFO()
            bmi.bmiHeader.biSize = ctypes.sizeof(BITMAPINFOHEADER)
            bmi.bmiHeader.biWidth = w
            bmi.bmiHeader.biHeight = -h
            bmi.bmiHeader.biPlanes = 1
            bmi.bmiHeader.biBitCount = 32
            bmi.bmiHeader.biCompression = BI_RGB

            buf_size = w * h * 4
            buf = (ctypes.c_ubyte * buf_size)()
            if not _GetDIBits(_aim_cache_mem, _aim_cache_bm, 0, h, buf, ctypes.byref(bmi), DIB_RGB_COLORS):
                return None

            center_x = w // 2
            center_y = h // 2
            best_dist = 99999999
            best_x, best_y = None, None
            total_x, total_y, count = 0, 0, 0
            min_y = 99999999
            max_y = -1
            step = 2 if aim_fov_size <= 80 else 3
            for py in range(0, h, step):
                row_offset = py * w * 4
                for px in range(0, w, step):
                    idx = row_offset + px * 4
                    r, g, b = buf[idx + 2], buf[idx + 1], buf[idx]
                    if color_matches(r, g, b, c_name):
                        dist_sq = (px - center_x) * (px - center_x) + (py - center_y) * (py - center_y)
                        if dist_sq < best_dist:
                            best_dist = dist_sq
                            best_x = px
                            best_y = py
                        total_x += px
                        total_y += py
                        count += 1
                        if py < min_y:
                            min_y = py
                        if py > max_y:
                            max_y = py

            if count > 0:
                if aim_headshot:
                    # KAFA HİZASI: hedefin üst %20'lik bölgesinin merkezine nişan al.
                    # (outline'ın en üstü = kafanın tepesi; biraz aşağı kaydırarak
                    #  kafa outline'ının içine nişan alırız)
                    head_cut = min_y + int((max_y - min_y) * 0.15)
                    if head_cut <= min_y:
                        head_cut = min_y + 1
                    hx_sum, hy_sum, h_cnt = 0, 0, 0
                    for py in range(0, head_cut + 1, step):
                        row_offset = py * w * 4
                        for px in range(0, w, step):
                            idx = row_offset + px * 4
                            r, g, b = buf[idx + 2], buf[idx + 1], buf[idx]
                            if color_matches(r, g, b, c_name):
                                hx_sum += px
                                hy_sum += py
                                h_cnt += 1
                    if h_cnt > 0:
                        target_x = x_start + hx_sum // h_cnt
                        target_y = y_start + hy_sum // h_cnt
                    else:
                        target_x = x_start + total_x // count
                        target_y = y_start + min_y
                else:
                    # GÖVDE: crosshair'e en yakın piksel ile kümenin merkezinin ortalaması
                    if best_x is not None and best_y is not None:
                        target_x = x_start + (best_x + (total_x // count)) // 2
                        target_y = y_start + (best_y + (total_y // count)) // 2
                    else:
                        target_x = x_start + total_x // count
                        target_y = y_start + total_y // count
                return target_x, target_y
        except Exception:
            _aim_gdi_cleanup()
        return None

# Interception mouse stroke yapısı (mouse hareketi için)
class _InterceptionMouseStrokeAim(ctypes.Structure):
    _fields_ = [
        ("state", ctypes.c_ushort),
        ("flags", ctypes.c_ushort),
        ("rolling", ctypes.c_short),
        ("x", ctypes.c_int),
        ("y", ctypes.c_int),
        ("information", ctypes.c_uint),
    ]

def _aimbot_smooth_move(target_x, target_y):
    """Smooth değerine göre fareyi hedefe yavaşça hareket ettir (Interception öncelikli, mouse_event fallback).
    Interception enjeksiyonu başarılıysa True döndürür."""
    sw = _GetSystemMetrics(0)
    sh = _GetSystemMetrics(1)
    cx, cy = sw // 2, sh // 2
    dx = target_x - cx
    dy = target_y - cy
    dist = (dx*dx + dy*dy) ** 0.5
    if dist < 1.5:
        return False

    # Smooth faktörüne göre bu frame'de kaç piksel gidileceği (%100 = anlık, %500 = 5x hız, %1 = çok yavaş)
    factor = max(0.05, min(5.0, aim_smooth / 100.0))
    move_x = int(dx * factor)
    move_y = int(dy * factor)
    if move_x == 0 and abs(dx) >= 1:
        move_x = 1 if dx > 0 else -1
    if move_y == 0 and abs(dy) >= 1:
        move_y = 1 if dy > 0 else -1

    # 1. Interception sürücüsü ile mouse hareketi (tüm mouse cihazlarına broadcast)
    _moved = False
    try:
        global _interception_dll, _interception_ctx
        if _interception_dll is None:
            _load_interception()
        if _interception_dll is not None and _interception_ctx is not None:
            stroke = _InterceptionMouseStrokeAim()
            stroke.state = 0
            stroke.flags = 0  # 0 = INTERCEPTION_MOUSE_MOVE_RELATIVE
            stroke.rolling = 0
            stroke.x = move_x
            stroke.y = move_y
            stroke.information = 0
            
            # Interception enjeksiyonu: önce fiziksel mouse cihazları (10..19),
            # hiçbiri kabul etmezse sanal mouse cihazları (30..39) dene.
            # İlk kabul eden cihaza TEK stroke gönder (birden fazla cihaz kabul
            # ederse çift hareket olmaması için).
            for dev in tuple(range(10, 20)) + tuple(range(30, 40)):
                ret = _interception_dll.interception_send(
                    _interception_ctx, dev,
                    ctypes.byref(stroke), 1
                )
                if ret > 0:
                    _moved = True
                    break
    except Exception:
        pass

    # 2. Fallback: interception başarısız olduysa mouse_event ile hareket
    # (çift hareket olmaması için sadece interception kabul etmediğinde çalışır)
    if not _moved:
        try:
            extra = _GetMessageExtraInfo()
            _mouse_event(MOUSEEVENTF_MOVE, move_x, move_y, 0, extra)
        except Exception:
            try:
                ctypes.windll.user32.SetCursorPos(target_x, target_y)
            except Exception:
                pass
    return _moved


def aimbot_thread():
    """Aimbot arka plan döngüsü."""
    global aim_active, aim_toggle_active, _last_aim_target
    prev_bind = False
    scan_counter = 0
    _last_aim_target = None
    _load_interception()
    print(f"{CYAN}[AIM] Aimbot thread başlatıldı (FOV={aim_fov_size}, Smooth=%{aim_smooth}){RESET}")
    while True:
        time.sleep(0.01)
        if not overlay_root or not aimbot_on:
            if aim_active:
                aim_active = False
            time.sleep(0.05)
            continue
        bind_pressed = is_key_pressed(aim_bind_vk)
        should_aim = False
        if aim_mode == "HOLD":
            should_aim = bind_pressed
        elif aim_mode == "TOGGLE":
            if bind_pressed and not prev_bind:
                aim_toggle_active = not aim_toggle_active
                state = "AKTIF" if aim_toggle_active else "KAPALI"
                print(f"{CYAN}[AIM] Aimbot: {state}{RESET}")
            should_aim = aim_toggle_active
        prev_bind = bind_pressed
        if should_aim:
            if not aim_active:
                aim_active = True
                print(f"{GREEN}[AIM] Hedef taraması başladı...{RESET}")
            target = _aimbot_find_target()
            if target:
                tx, ty = target
                _aimbot_smooth_move(tx, ty)
                scan_counter = 0
                if _last_aim_target is None:
                    print(f"{GREEN}[AIM] Hedef bulundu: ({tx}, {ty}){RESET}")
                _last_aim_target = (tx, ty)
            else:
                _last_aim_target = None
                scan_counter += 1
                if scan_counter == 50:
                    scan_counter = 0
        else:
            if aim_active:
                aim_active = False
                print(f"{YELLOW}[AIM] Hedef taraması durdu{RESET}")

