def load_agent_images():
    """Resimler klasöründen tüm resmi Valorant ajan ikonlarını dinamik yükler (Embedded base64)."""
    global agent_images, small_agent_images
    global EMBEDDED_AGENT_ICONS
    if 'EMBEDDED_AGENT_ICONS' in globals() and EMBEDDED_AGENT_ICONS:
        import io
        import base64
        for a_name, b64_data in EMBEDDED_AGENT_ICONS.items():
            try:
                img_data = base64.b64decode(b64_data)
                raw_img = Image.open(io.BytesIO(img_data)).convert("RGBA")
                
                img = raw_img.resize((42, 42), Image.Resampling.LANCZOS)
                agent_images[a_name] = ImageTk.PhotoImage(img)
                
                img_small = raw_img.resize((22, 22), Image.Resampling.LANCZOS)
                small_agent_images[a_name] = ImageTk.PhotoImage(img_small)
            except Exception:
                pass

def load_rank_images():
    """Rank ikonları klasöründen tüm rank resimlerini yükler (Embedded base64)."""
