def toggle_overlay_passthrough(transparent_active):
    """Overlay penceresinin fare tıklamalarını geçirip geçirmeyeceğini ayarlar."""
    if not overlay_root:
        return
    try:
        hwnd = int(overlay_root.wm_frame(), 16)
        if hwnd:
            cur_style = _GetWindowLongW(hwnd, GWL_EXSTYLE)
            if transparent_active:
                new_style = cur_style | WS_EX_TRANSPARENT
            else:
                new_style = cur_style & ~WS_EX_TRANSPARENT
            _SetWindowLongW(hwnd, GWL_EXSTYLE, new_style)
    except Exception:
        pass

def apply_stream_proof(enable):
    """Donanım seviyesinde Stream Proof uygulayan Win32 API çağrısı (OBS/Discord gizleme)."""
    if not overlay_root:
        return
    try:
        hwnd = int(overlay_root.wm_frame(), 16)
        if hwnd:
            WDA_NONE = 0x00000000
            WDA_EXCLUDEFROMCAPTURE = 0x00000011
            affinity = WDA_EXCLUDEFROMCAPTURE if enable else WDA_NONE
            res = ctypes.windll.user32.SetWindowDisplayAffinity(hwnd, affinity)
            if not res and enable:
                ctypes.windll.user32.SetWindowDisplayAffinity(hwnd, 0x00000001)
    except Exception:
        pass

def update_led():
    """LED ışığının rengini günceller."""
    if led_canvas and led_oval_id:
        if led_triggered:
            led_canvas.itemconfig(led_oval_id, fill="#00FF66", outline="#00CC55")
        elif aim_active:
            led_canvas.itemconfig(led_oval_id, fill="#00FF66", outline="#00CC55")
        elif scan_active:
            led_canvas.itemconfig(led_oval_id, fill="#00F0FF", outline="#00AACC")
        else:
            led_canvas.itemconfig(led_oval_id, fill="#2A2D3D", outline="#1A1C29")

def draw_agent_card(canvas, agent_name, is_selected):
    """50x50 Ajan kartını resmi fotoğrafı ile çizer."""
    canvas.delete("all")
    role_name, role_color = AGENT_ROLES.get(agent_name, ("OTHER", "#A0A5B5"))
    
    bg_col = "#1E202B" if is_selected else "#14141A"
    bd_col = "#00F0FF" if is_selected else "#262632"
    bd_width = 2 if is_selected else 1
    
    canvas.create_rectangle(1, 1, 49, 49, fill=bg_col, outline=bd_col, width=bd_width)
    
    if agent_name in agent_images:
        canvas.create_image(25, 25, image=agent_images[agent_name])
    else:
        disp_name = agent_name if len(agent_name) <= 6 else agent_name[:5]
        canvas.create_text(25, 25, text=disp_name, font=("Consolas", 8, "bold"), fill="#FFFFFF" if is_selected else "#A0A5B5")
        
    canvas.create_rectangle(2, 2, 48, 5, fill=role_color, outline="")
    
    if is_selected:
        canvas.create_rectangle(2, 2, 48, 48, fill="", outline="#00F0FF", width=2)

def _select_row_by_index(idx):
    global selected_index
    selected_index = idx
    if overlay_root:
        overlay_root.after(0, update_overlay_ui)

def _apply_row_action(key, direction):
    global trigger_on, color_index, trigger_mode, trigger_bind_vk, trigger_bind_name, waiting_for_bind
    global fire_mode, FIRE_KEY_VK, FIRE_KEY_NAME, fire_delay, draw_fov_on, fov_size, humanizer_on
    global headshot_priority_on, multi_ms_on, instalock_on, show_agent_on, agent_index
    global player_region, region_index, sproof_on, bhop_on, autopistol_on, anti_afk_on
    global watermark_on, watermark_rainbow, discord_rpc_on, auto_crouch_on, snap_tap_on
    global center_dot_on, recoil_assist_on, counter_strafe_on, eco_tracker_on
    global sec_bypass_level, sec_title_mask, sec_delay_jitter, sec_scan_jitter
    global aimbot_on, aim_mode, aim_bind_vk, aim_bind_name, aim_fov_size, aim_smooth, aim_headshot, aim_show_fov, waiting_for_bind, waiting_for_aim_bind
    
    is_right = (direction == "right")
    changed = True

    if current_tab == 0:
        if key == 'trigger':
            trigger_on = not trigger_on
            if not trigger_on:
                toggle_active = False
        elif key == 'color':
            color_index = (color_index + (1 if is_right else -1)) % len(color_options)
        elif key == 'trigger_mode':
            trigger_mode = "TOGGLE" if trigger_mode == "HOLD" else "HOLD"
            toggle_active = False
        elif key == 'trigger_bind':
            if is_right:
                waiting_for_bind = True
            else:
                trigger_bind_vk = VK_CAPITAL
                trigger_bind_name = "CAPS LOCK"
                waiting_for_bind = False
        elif key == 'fire_mode':
            fire_mode = "INTERCEPTION"
        elif key == 'fire_key':
            if is_right:
                waiting_for_fire_bind = True
            else:
                FIRE_KEY_VK = 0x4B
                FIRE_KEY_NAME = "K"
                waiting_for_fire_bind = False
        elif key == 'fire_speed':
            if is_right:
                fire_delay = min(200, fire_delay + 5)
            else:
                fire_delay = max(0, fire_delay - 5)
        elif key == 'draw_fov':
            draw_fov_on = not draw_fov_on
        elif key == 'fov':
            presets = [3, 4, 5, 7, 10, 20, 30, 50, 60, 80, 100, 150, 200, 300]
            idx = presets.index(fov_size) if fov_size in presets else 0
            idx = (idx + (1 if is_right else -1)) % len(presets)
            fov_size = presets[idx]
        elif key == 'humanizer':
            humanizer_on = not humanizer_on
        elif key == 'headshot_priority':
            headshot_priority_on = not headshot_priority_on
        elif key == 'multi_ms':
            multi_ms_on = not multi_ms_on
        else:
            changed = False
    elif current_tab == 1:  # AIMBOT TAB
        if key == 'aimbot':
            aimbot_on = not aimbot_on
        elif key == 'aim_mode':
            aim_mode = "TOGGLE" if aim_mode == "HOLD" else "HOLD"
        elif key == 'aim_bind':
            if is_right:
                waiting_for_aim_bind = True
            else:
                aim_bind_vk = VK_MENU
                aim_bind_name = "ALT"
                waiting_for_aim_bind = False
        elif key == 'aim_smooth':
            aim_smooth = max(1, min(500, aim_smooth + (25 if is_right else -25)))
        elif key == 'aim_headshot':
            aim_headshot = not aim_headshot
        elif key == 'aim_show_fov':
            aim_show_fov = not aim_show_fov
        elif key == 'aim_fov':
            aim_fov_size = max(20, min(400, aim_fov_size + (10 if is_right else -10)))
        else:
            changed = False
    elif current_tab == 2:  # INSTALOCK TAB
        if key == 'instalock':
            instalock_on = not instalock_on
        elif key == 'show_agent':
            show_agent_on = not show_agent_on
        elif key == 'icharacter':
            agent_index = (agent_index + (1 if is_right else -1)) % len(agent_options)
        else:
            changed = False
    elif current_tab == 3:  # OYUNCULAR TAB
        if key == 'player_region':
            region_options = ["eu", "na", "ap", "kr"]
            region_index = (region_index + (1 if is_right else -1)) % len(region_options)
            player_region = region_options[region_index]
        elif key == 'refresh_players':
            fetch_live_match_data()
        else:
            changed = False
    elif current_tab == 4:  # MISC TAB
        if key == 'sproof':
            sproof_on = not sproof_on
        elif key == 'bhop':
            bhop_on = not bhop_on
        elif key == 'autopistol':
            autopistol_on = not autopistol_on
        elif key == 'anti_afk':
            anti_afk_on = not anti_afk_on
        elif key == 'watermark':
            watermark_on = not watermark_on
        elif key == 'watermark_rb':
            watermark_rainbow = not watermark_rainbow
        elif key == 'discord_rpc':
            discord_rpc_on = not discord_rpc_on
        elif key == 'auto_crouch':
            auto_crouch_on = not auto_crouch_on
        elif key == 'snap_tap':
            snap_tap_on = not snap_tap_on
        elif key == 'center_dot':
            center_dot_on = not center_dot_on
        elif key == 'recoil_assist':
            recoil_assist_on = not recoil_assist_on
        elif key == 'counter_strafe':
            counter_strafe_on = not counter_strafe_on
        elif key == 'eco_tracker':
            eco_tracker_on = not eco_tracker_on
        else:
            changed = False
    elif current_tab == 5:  # SECURITY TAB
        if key == 'sec_bypass':
            sec_bypass_level = (sec_bypass_level + (1 if is_right else -1)) % 3
        elif key == 'sec_mask':
            sec_title_mask = (sec_title_mask + (1 if is_right else -1)) % 5
        elif key == 'sec_jitter':
            sec_delay_jitter = (sec_delay_jitter + (1 if is_right else -1)) % 4
        elif key == 'sec_scan_jit':
            sec_scan_jitter = not sec_scan_jitter
        else:
            changed = False

    if changed:
        save_config()

def set_row_state(key, index, title_text, val_text, val_color, is_disabled=False):
    """Menü satırının aktif/pasif ve seçili durum renklerini günceller."""
    if key not in labels_dict:
        return
    _menu_keys[key] = index
    w = labels_dict[key]
    is_sel = (selected_index == index)
    
    bg_col = "#1E202B" if is_sel else "#14141A"
    prefix_text = "▶ " if is_sel else "  "
    prefix_col = "#00F0FF" if is_sel else "#14141A"
    title_col = "#FFFFFF" if is_sel else ("#555B6E" if is_disabled else "#A0A5B5")
    
    w['frame'].config(bg=bg_col)
    w['prefix'].config(text=prefix_text, fg=prefix_col, bg=bg_col)
    w['title'].config(text=title_text, fg=title_col, bg=bg_col)
    w['val'].config(text=val_text, fg="#555B6E" if is_disabled else val_color, bg=bg_col)

def update_overlay_ui():
    """Menüdeki görsel elemanları ve FOV çizimini günceller."""
    if not overlay_root or not labels_dict:
        return
    
    if main_frame_widget:
        if menu_visible:
            main_frame_widget.place(x=60, y=60)
            toggle_overlay_passthrough(transparent_active=False)
        else:
            main_frame_widget.place_forget()
            toggle_overlay_passthrough(transparent_active=True)

    apply_stream_proof(sproof_on)

    for t_idx, b_widget in tab_buttons.items():
        if t_idx == current_tab:
            b_widget.config(bg="#222430", fg="#00F0FF", font=("Segoe UI", 9, "bold"))
        else:
            b_widget.config(bg="#14141A", fg="#8A8A9E", font=("Segoe UI", 9))
        b_widget.unbind("<Enter>")
        b_widget.unbind("<Leave>")
        def _make_tab_hover(idx):
            def _on_enter(e):
                if current_tab != idx:
                    e.widget.config(bg="#1E202B")
            def _on_leave(e):
                if current_tab != idx:
                    e.widget.config(bg="#14141A")
            return _on_enter, _on_leave
