def _row_on_enter(e, key):
    row_data = labels_dict.get(key)
    if not row_data:
        return
    if key in _menu_keys and _menu_keys[key] == selected_index:
        return
    for w in [row_data['frame'], row_data['prefix'], row_data['title'], row_data['val']]:
        try:
            w.config(bg="#1A1C26")
        except:
            pass

def _row_on_leave(e, key):
    row_data = labels_dict.get(key)
    if not row_data:
        return
    is_sel = (key in _menu_keys and _menu_keys[key] == selected_index)
    bg = "#1E202B" if is_sel else "#14141A"
    for w in [row_data['frame'], row_data['prefix'], row_data['title'], row_data['val']]:
        try:
            w.config(bg=bg)
        except:
            pass

def _row_on_click(e, key):
    if key in _menu_keys:
        idx = _menu_keys[key]
        _select_row_by_index(idx)
        if overlay_root:
            overlay_root.after(0, update_overlay_ui)

_aim_bind_popup_open = False

def _show_aim_bind_popup():
    """Aim bind için büyük ve kullanışlı tuş yakalama popup'u gösterir."""
    global waiting_for_aim_bind, _aim_bind_popup_open
    if _aim_bind_popup_open:
        return
    _aim_bind_popup_open = True
    waiting_for_aim_bind = True
    
    popup = tk.Toplevel(overlay_root)
    popup.title("AIM KEY SEÇ")
    popup.geometry("320x180+%d+%d" % (
        overlay_root.winfo_screenwidth()//2 - 160,
        overlay_root.winfo_screenheight()//2 - 90
    ))
    popup.configure(bg="#0F0F12")
    popup.resizable(False, False)
    popup.attributes("-topmost", True)
    popup.grab_set()
    
    tk.Label(popup, text="⚡ AIM BIND KEY SEÇ", font=("Segoe UI", 12, "bold"),
             bg="#0F0F12", fg="#00F0FF").pack(pady=(18, 6))
    tk.Label(popup, text="Herhangi bir tuşa basın...", font=("Segoe UI", 10),
             bg="#0F0F12", fg="#A0A5B5").pack(pady=4)
    
    lbl_key = tk.Label(popup, text="[ BEKLENIYOR... ]", font=("Segoe UI", 13, "bold"),
                       bg="#0F0F12", fg="#FFDD00")
    lbl_key.pack(pady=10)
    
    def _on_key(event):
        global aim_bind_vk, aim_bind_name, waiting_for_aim_bind, _aim_bind_popup_open
        keysym = event.keysym
        # Keycode → VK dönüşümü
        vk = event.keycode
        # Özel bazı tuşlar için isim éşle
        special_names = {
            65513: "ALT", 65514: "ALT",
            65505: "SHIFT", 65506: "SHIFT",
            65507: "CTRL", 65508: "CTRL",
            65289: "TAB",
            65293: "ENTER",
        }
        # Windows VK için GetAsyncKeyState ile bul
        captured_vk = None
        captured_name = None
        for v in range(1, 256):
            try:
                state = ctypes.windll.user32.GetAsyncKeyState(v)
                if state & 0x8000:
                    captured_vk = v
                    captured_name = get_vk_name(v)
                    break
            except Exception:
                pass
        if captured_vk and captured_vk not in {VK_INSERT, 0x1B}:
            aim_bind_vk = captured_vk
            aim_bind_name = captured_name
            waiting_for_aim_bind = False
            _aim_bind_popup_open = False
            lbl_key.config(text=f"[ {captured_name} ]", fg="#00FF66")
            save_config()
            if overlay_root:
                overlay_root.after(0, update_overlay_ui)
            popup.after(400, popup.destroy)
        elif keysym == 'Escape':
            waiting_for_aim_bind = False
            _aim_bind_popup_open = False
            popup.destroy()
    
    popup.bind("<KeyPress>", _on_key)
    popup.focus_set()
    
    cancel_btn = tk.Label(popup, text="✕ İptal (ESC)", font=("Segoe UI", 9),
                          bg="#0F0F12", fg="#FF4466", cursor="hand2")
    cancel_btn.pack(pady=(0, 10))
    
    def _cancel(e=None):
        global waiting_for_aim_bind, _aim_bind_popup_open
        waiting_for_aim_bind = False
        _aim_bind_popup_open = False
        try:
            popup.destroy()
        except Exception:
            pass
    cancel_btn.bind("<Button-1>", _cancel)
    popup.protocol("WM_DELETE_WINDOW", _cancel)

def _row_val_click(e, key, direction):
    if key == 'aim_bind' and direction == 'right':
        # Aim bind için özel popup aç
        if overlay_root:
            overlay_root.after(0, _show_aim_bind_popup)
        return
    _row_on_click(e, key)
    _apply_row_action(key, direction)
    if overlay_root:
        overlay_root.after(0, update_overlay_ui)

_menu_keys = {}

def create_menu_row(parent, key, default_title, default_val):
    row = tk.Frame(parent, bg="#14141A", padx=8, pady=4, cursor="hand2")
    row.pack(fill="x", pady=1)
    
    lbl_p = tk.Label(row, text="  ", font=("Consolas", 10, "bold"), bg="#14141A", fg="#14141A", width=2, anchor="w")
    lbl_p.pack(side="left")
    
    lbl_t = tk.Label(row, text=default_title, font=("Segoe UI", 9, "bold"), bg="#14141A", fg="#A0A5B5", anchor="w")
    lbl_t.pack(side="left")
    
    lbl_v = tk.Label(row, text=default_val, font=("Segoe UI", 9, "bold"), bg="#14141A", fg="#00F0FF", anchor="e", cursor="hand2")
    lbl_v.pack(side="right", padx=(10, 5))
    
    labels_dict[key] = {'frame': row, 'prefix': lbl_p, 'title': lbl_t, 'val': lbl_v}
    
    row.bind("<Enter>", lambda e, k=key: _row_on_enter(e, k))
    row.bind("<Leave>", lambda e, k=key: _row_on_leave(e, k))
    row.bind("<Button-1>", lambda e, k=key: _row_on_click(e, k))
    lbl_t.bind("<Enter>", lambda e, k=key: _row_on_enter(e, k))
    lbl_t.bind("<Leave>", lambda e, k=key: _row_on_leave(e, k))
    lbl_t.bind("<Button-1>", lambda e, k=key: _row_on_click(e, k))
    lbl_p.bind("<Enter>", lambda e, k=key: _row_on_enter(e, k))
    lbl_p.bind("<Leave>", lambda e, k=key: _row_on_leave(e, k))
    lbl_p.bind("<Button-1>", lambda e, k=key: _row_on_click(e, k))
    lbl_v.bind("<Enter>", lambda e, k=key: _row_on_enter(e, k))
    lbl_v.bind("<Leave>", lambda e, k=key: _row_on_leave(e, k))
    lbl_v.bind("<Button-1>", lambda e, k=key: _row_val_click(e, k, "right"))
    lbl_v.bind("<Button-3>", lambda e, k=key: _row_val_click(e, k, "left"))

def select_agent_by_mouse(idx):
    global agent_index, selected_index
    agent_index = idx
    selected_index = 2
    save_config()
    if overlay_root:
        overlay_root.after(0, update_overlay_ui)

def fetch_live_match_data():
    """Riot Local Client, GLZ Match API ve HenrikDev API kullanarak canlı maç oyuncularını çeker."""
    global match_teams_data, match_status_text
    match_status_text = "Yükleniyor..."
    if overlay_root:
        overlay_root.after(0, update_overlay_ui)
        
    def worker():
        global match_teams_data, match_status_text
        try:
            lf_path = os.path.expandvars(r'%LocalAppData%\Riot Games\Riot Client\Config\lockfile')
            if not os.path.exists(lf_path):
                match_status_text = "Riot Client Kapalı"
                if overlay_root: overlay_root.after(0, update_overlay_ui)
                return
                
            with open(lf_path, 'r') as f:
                parts = f.read().split(':')
                port, pwd = parts[2], parts[3]

            import urllib3, base64, json
            urllib3.disable_warnings()

            # Custom requests mock using urllib3 to bypass Windows Defender pip blocks
            class UrllibRequestsMock:
                def __init__(self):
                    self.http = urllib3.PoolManager(cert_reqs='CERT_NONE')
                class ResponseMock:
                    def __init__(self, status_code, data):
                        self.status_code = status_code
                        self.data = data
                    def json(self):
                        return json.loads(self.data.decode('utf-8', errors='ignore'))
                def get(self, url, headers=None, verify=True, timeout=None):
                    t = timeout
                    if isinstance(t, tuple):
                        t = t[0] + t[1]
                    r = self.http.request('GET', url, headers=headers, timeout=t)
                    return self.ResponseMock(r.status, r.data)
                def put(self, url, headers=None, json=None, verify=True, timeout=None):
                    t = timeout
                    if isinstance(t, tuple):
                        t = t[0] + t[1]
                    body = json.dumps(json) if json is not None else None
                    r = self.http.request('PUT', url, headers=headers, body=body, timeout=t)
                    return self.ResponseMock(r.status, r.data)
            requests = UrllibRequestsMock()

            auth = base64.b64encode(f"riot:{pwd}".encode()).decode()
            headers_local = {'Authorization': f"Basic {auth}"}

            # Get presences to map PUUID to party ID, level, and rank
            puuid_to_party = {}
            puuid_to_level = {}
            puuid_to_rank_presence = {}
            try:
                r_pres = requests.get(f"https://127.0.0.1:{port}/chat/v4/presences", headers=headers_local, verify=False, timeout=3)
                if r_pres.status_code == 200:
                    for p in r_pres.json().get('presences', []):
                        pid_val = p.get('puuid')
                        private_b64 = p.get('private', '')
                        if pid_val and private_b64:
                            try:
                                missing_padding = len(private_b64) % 4
                                if missing_padding:
                                    private_b64 += '=' * (4 - missing_padding)
                                decoded_str = base64.b64decode(private_b64).decode('utf-8', errors='ignore')
                                private_data = json.loads(decoded_str)
                                party_id = (
                                    private_data.get('partyId') or 
                                    private_data.get('partyID') or 
                                    private_data.get('PartyId') or 
                                    private_data.get('PartyID') or 
                                    private_data.get('party_id')
                                )
                                if party_id:
                                    puuid_to_party[pid_val] = party_id
                                    
                                lvl_presence = (
                                    private_data.get('accountLevel') or 
                                    private_data.get('account_level') or 
                                    private_data.get('AccountLevel')
                                )
                                if lvl_presence:
                                    puuid_to_level[pid_val] = int(lvl_presence)
                                    
                                tier_presence = (
                                    private_data.get('competitiveTier') or 
                                    private_data.get('competitive_tier') or 
                                    private_data.get('CompetitiveTier')
                                )
                                if tier_presence is not None:
                                    puuid_to_rank_presence[pid_val] = int(tier_presence)
                            except Exception:
                                pass
            except Exception:
                pass
            
            r_tok = requests.get(f"https://127.0.0.1:{port}/entitlements/v1/token", headers=headers_local, verify=False, timeout=3)
            if r_tok.status_code != 200:
                match_status_text = "Token Alınamadı"
                if overlay_root: overlay_root.after(0, update_overlay_ui)
                return
                
            tok_data = r_tok.json()
            acc_token = tok_data.get('accessToken')
            ent_token = tok_data.get('token')
            sub = tok_data.get('subject')
            
            # Valorant version
            c_ver = "release-08.11-shipping-14-2615694"
            try:
                rv = requests.get("https://valorant-api.com/v1/version", timeout=2)
                if rv.status_code == 200:
                    c_ver = rv.json().get('data', {}).get('riotClientVersion', c_ver)
            except Exception:
                pass
                
            cp = {"platformType": "PC", "platformOS": "Windows", "platformOSVersion": "10.0.19041.1.256.64bit", "platformChipset": "Unknown"}
            cp_b64 = base64.b64encode(json.dumps(cp).encode()).decode()
            
            headers_remote = {
                'Authorization': f"Bearer {acc_token}",
                'X-Riot-Entitlements-JWT': ent_token,
                'X-Riot-ClientVersion': c_ver,
                'X-Riot-ClientPlatform': cp_b64
            }
            
            # Agent listesi (UUID -> Name)
            agents_map = {}
            try:
                ra = requests.get("https://valorant-api.com/v1/agents?isPlayableCharacter=true", timeout=3)
                if ra.status_code == 200:
                    agents_map = {a['uuid'].lower(): a['displayName'] for a in ra.json().get('data', [])}
            except Exception:
                pass

            raw_players = []
            my_team_id = None
            in_match = False

            # 1. Core-Game dene
            r_cg = requests.get(f"https://glz-{player_region}-1.{player_region}.a.pvp.net/core-game/v1/players/{sub}", headers=headers_remote, verify=False, timeout=3)
            if r_cg.status_code == 200:
                m_id = r_cg.json().get('MatchID')
                r_m = requests.get(f"https://glz-{player_region}-1.{player_region}.a.pvp.net/core-game/v1/matches/{m_id}", headers=headers_remote, verify=False, timeout=4)
                if r_m.status_code == 200:
                    in_match = True
                    p_list = r_m.json().get('Players', [])
                    for p in p_list:
                        s = p.get('Subject')
                        t_id = p.get('TeamID')
                        c_id = p.get('CharacterID', '').lower()
                        lvl = p.get('PlayerIdentity', {}).get('AccountLevel', 0)
                        pty_id = p.get('PartyID') or p.get('party_id') or puuid_to_party.get(s)
                        if s == sub:
                            my_team_id = t_id
                        raw_players.append({'puuid': s, 'team_id': t_id, 'agent': agents_map.get(c_id, 'Bilinmiyor'), 'level': lvl, 'party_id': pty_id})
                        
            # 2. Pre-Game dene (Eğer Core-Game yoksa)
            if not in_match:
                r_pg = requests.get(f"https://glz-{player_region}-1.{player_region}.a.pvp.net/pregame/v1/players/{sub}", headers=headers_remote, verify=False, timeout=3)
                if r_pg.status_code == 200:
                    m_id = r_pg.json().get('MatchID')
                    r_m = requests.get(f"https://glz-{player_region}-1.{player_region}.a.pvp.net/pregame/v1/matches/{m_id}", headers=headers_remote, verify=False, timeout=4)
                    if r_m.status_code == 200:
                        in_match = True
                        m_j = r_m.json()
                        ally_players = m_j.get('AllyTeam', {}).get('Players', [])
                        my_team_id = m_j.get('AllyTeam', {}).get('TeamID', 'Blue')
                        for p in ally_players:
                            s = p.get('Subject')
                            c_id = p.get('CharacterID', '').lower()
                            pty_id = p.get('PartyID') or p.get('party_id') or puuid_to_party.get(s)
                            raw_players.append({'puuid': s, 'team_id': my_team_id, 'agent': agents_map.get(c_id, 'Seçiliyor...'), 'level': 0, 'party_id': pty_id})

            # 3. Fallback (Maçta değilse Lobi / Presences)
            if not raw_players:
                r_pres = requests.get(f"https://127.0.0.1:{port}/chat/v4/presences", headers=headers_local, verify=False, timeout=3)
                if r_pres.status_code == 200:
                    for p in r_pres.json().get('presences', []):
                        if p.get('product') == 'valorant' and p.get('game_name'):
                            raw_players.append({
                                'puuid': p.get('puuid'),
                                'team_id': 'Blue',
                                'agent': 'Lobi',
                                'level': 0,
                                'direct_name': f"{p.get('game_name')}#{p.get('game_tag')}",
                                'g_name': p.get('game_name'),
                                'g_tag': p.get('game_tag'),
                                'party_id': puuid_to_party.get(p.get('puuid'))
                            })
                my_team_id = 'Blue'

            if not raw_players:
                match_status_text = "Aktif Maç/Oyuncu Yok"
                match_teams_data = {'my_team': [], 'enemy_team': []}
                if overlay_root: overlay_root.after(0, update_overlay_ui)
                return

            # Name Service ile İsimleri Çöz
            puuids_to_resolve = [p['puuid'] for p in raw_players if 'direct_name' not in p]
            names_map = {}
            if puuids_to_resolve:
                try:
                    rn = requests.put(f"https://pd.{player_region}.a.pvp.net/name-service/v2/players", headers=headers_remote, json=puuids_to_resolve, verify=False, timeout=4)
                    if rn.status_code == 200:
                        for item in rn.json():
                            names_map[item['Subject']] = (item['GameName'], item['TagLine'])
                except Exception:
                    pass

            # HenrikDev API ile Rank & Peak Rank Çek
            h_headers = {}
            if henrik_api_key:
                h_headers['Authorization'] = henrik_api_key

            my_team_list = []
            enemy_team_list = []

            # Party (Grup) Eşleştirme Analizi
            party_counts = {}
            for p in raw_players:
                pid = p.get('party_id')
                if pid and pid != "00000000-0000-0000-0000-000000000000":
                    party_counts[pid] = party_counts.get(pid, 0) + 1

            party_colors = ["#FF00FF", "#00FFFF", "#FFFF00", "#FF8800", "#00FF66", "#FF4466"]
            party_map = {}
            p_idx = 0
            for pid, count in party_counts.items():
                if count >= 2:
                    party_map[pid] = (f"G{p_idx + 1}", party_colors[p_idx % len(party_colors)])
                    p_idx += 1

            def fetch_single_player_data(p):
                puuid = p['puuid']
                if 'g_name' in p:
                    g_name, g_tag = p['g_name'], p['g_tag']
                else:
                    g_name, g_tag = names_map.get(puuid, ("Oyuncu", "TR1"))

                full_name = f"{g_name}#{g_tag}"
                rank_str = "Bilinmiyor"
                rr_str = "-"
                peak_str = "-"
                lvl_val = p.get('level', 0)

                # Try Riot MMR API directly first
                try:
                    url_riot_mmr = f"https://pd.{player_region}.a.pvp.net/mmr/v1/players/{puuid}"
                    res_riot = requests.get(url_riot_mmr, headers=headers_remote, verify=False, timeout=3)
                    if res_riot.status_code == 200:
                        riot_data = res_riot.json()
                        latest_tier = riot_data.get('LatestSemesterCompetitiveTier', 0)
                        latest_rr = riot_data.get('LatestSemesterRankedRating', 0)
                        
                        rank_str = VALORANT_TIERS.get(latest_tier, "Unranked")
                        rr_str = f"{latest_rr} RR"
                        
                        # Find Peak Rank in SeasonalInfoBySeasonID
                        peak_tier = latest_tier
                        q_skills = riot_data.get('QueueSkills', {})
                        if q_skills:
                            comp_skills = q_skills.get('competitive', {})
                            if comp_skills:
                                seasonal_info = comp_skills.get('SeasonalInfoBySeasonID', {})
                                if seasonal_info:
                                    for s_id, s_info in seasonal_info.items():
                                        tier = s_info.get('CompetitiveTier', 0)
                                        if tier > peak_tier:
                                            peak_tier = tier
                        peak_str = VALORANT_TIERS.get(peak_tier, "Unranked")
                    else:
                        raise Exception("Riot MMR API Failed")
                except Exception:
                    # Fallback to local presences if found
                    pres_tier = puuid_to_rank_presence.get(puuid)
                    if pres_tier is not None:
                        rank_str = VALORANT_TIERS.get(pres_tier, "Unranked")
                        rr_str = "- RR"
                        peak_str = rank_str
                    else:
                        # Fallback to HenrikDev API if key is available
                        if henrik_api_key:
                            try:
                                url_mmr = f"https://api.henrikdev.xyz/valorant/v2/by-puuid/mmr/{player_region}/{puuid}"
                                res_mmr = requests.get(url_mmr, headers=h_headers, timeout=3)
                                if res_mmr.status_code == 200:
                                    m_d = res_mmr.json().get('data', {})
                                    c_d = m_d.get('current_data', {})
                                    rank_str = c_d.get('currenttier_patched', c_d.get('currenttierpatched', 'Unranked'))
                                    rr_str = f"{c_d.get('ranking_in_tier', 0)} RR"
                                    h_d = m_d.get('highest_rank', {})
                                    peak_str = h_d.get('patched_tier', '-')
                                elif res_mmr.status_code in (401, 403):
                                    rank_str = "API Key Hatalı"
                                elif res_mmr.status_code == 429:
                                    rank_str = "Limit Aşıldı (429)"
                            except Exception:
                                pass
                        else:
                            rank_str = "API Key Lazım"

                # Resolve player level
                if lvl_val <= 0:
                    lvl_val = puuid_to_level.get(puuid, 0)
                
                if lvl_val <= 0 and henrik_api_key:
                    try:
                        url_acc = f"https://api.henrikdev.xyz/valorant/by-puuid/v2/account/{puuid}"
                        res_acc = requests.get(url_acc, headers=h_headers, timeout=2)
                        if res_acc.status_code == 200:
                            lvl_val = res_acc.json().get('data', {}).get('account_level', lvl_val)
                    except Exception:
                        pass

                pid = p.get('party_id')
                p_info = party_map.get(pid) if (pid and pid != "00000000-0000-0000-0000-000000000000") else None
                p_lbl = p_info[0] if p_info else "-"
                p_col = p_info[1] if p_info else "#555B6E"

                return {
                    'name': full_name,
                    'agent': p['agent'],
                    'level': lvl_val,
                    'rank': rank_str,
                    'rr': rr_str,
                    'peak': peak_str,
                    'party_label': p_lbl,
                    'party_color': p_col,
                    'team_id': p['team_id']
                }

            from concurrent.futures import ThreadPoolExecutor
            with ThreadPoolExecutor(max_workers=10) as executor:
                results = list(executor.map(fetch_single_player_data, raw_players[:12]))

            for p_data in results:
                if p_data['team_id'] == my_team_id or my_team_id is None:
                    my_team_list.append(p_data)
                else:
                    enemy_team_list.append(p_data)

            # Enemy Eco Tahmini
            avg_lvl = sum([p['level'] for p in enemy_team_list]) / max(1, len(enemy_team_list))
            if avg_lvl > 100 or len(enemy_team_list) >= 4:
                eco_status_str = "FULL BUY 💰 (Vandal / Armor)"
            else:
                eco_status_str = "SEMI ECO / PISTOL ⚠️"

            match_teams_data = {'my_team': my_team_list, 'enemy_team': enemy_team_list, 'enemy_eco': eco_status_str}
            tot = len(my_team_list) + len(enemy_team_list)
            match_status_text = f"Canlı Maç ({tot} Oyuncu)" if in_match else f"Lobi ({tot} Oyuncu)"

        except Exception:
            match_status_text = "Hata Oluştu"

        if overlay_root:
            overlay_root.after(0, update_overlay_ui)

    threading.Thread(target=worker, daemon=True).start()

def update_player_list_ui():
    global player_list_container, player_labels_widgets
    if not player_list_container:
        return
    for w in player_labels_widgets:
        w.destroy()
    player_labels_widgets.clear()
    
    my_team = match_teams_data.get('my_team', [])
    enemy_team = match_teams_data.get('enemy_team', [])
    
    if not my_team and not enemy_team:
        lbl = tk.Label(player_list_container, text="Oyuncu verisi yok.\nYenilemek için Sağ Ok'a basın.", font=("Consolas", 9), bg="#14141A", fg="#8A8A9E", pady=15)
        lbl.pack(fill="x")
        player_labels_widgets.append(lbl)
        return

    def render_section(title, players, title_color):
        if not players:
            return
        hdr = tk.Label(player_list_container, text=f"── {title} ({len(players)}) ──", font=("Segoe UI", 9, "bold"), bg="#14141A", fg=title_color, anchor="w", pady=3)
        hdr.pack(fill="x", padx=4)
        player_labels_widgets.append(hdr)
        
        # Tracker.gg Style Header Row (Clean, icons only)
        h_row = tk.Frame(player_list_container, bg="#1E1E28", pady=3, padx=4)
        h_row.pack(fill="x", pady=1)
        
        tk.Label(h_row, text=" AJAN", font=("Consolas", 8, "bold"), bg="#1E1E28", fg="#8A8A9E", width=5, anchor="w").pack(side="left")
        tk.Label(h_row, text="OYUNCU (NAME#TAG)", font=("Consolas", 8, "bold"), bg="#1E1E28", fg="#8A8A9E", width=20, anchor="w").pack(side="left", padx=(6, 0))
        tk.Label(h_row, text="GRUP", font=("Consolas", 8, "bold"), bg="#1E1E28", fg="#8A8A9E", width=6, anchor="center").pack(side="left", padx=(4, 0))
        tk.Label(h_row, text="LVL", font=("Consolas", 8, "bold"), bg="#1E1E28", fg="#8A8A9E", width=5, anchor="w").pack(side="left", padx=(4, 0))
        tk.Label(h_row, text="RANK", font=("Consolas", 8, "bold"), bg="#1E1E28", fg="#8A8A9E", width=12, anchor="w").pack(side="left", padx=(4, 0))
        tk.Label(h_row, text="PEAK", font=("Consolas", 8, "bold"), bg="#1E1E28", fg="#8A8A9E", width=6, anchor="e").pack(side="right", padx=6)
        player_labels_widgets.append(h_row)

        for idx, p in enumerate(players):
            r_bg = "#1A1A26" if idx % 2 == 0 else "#14141A"
            row = tk.Frame(player_list_container, bg=r_bg, pady=3, padx=4)
            row.pack(fill="x", pady=1)
            
            # 1. Agent Icon ONLY (no name text)
            ag_key = p['agent'].upper()
            if ag_key == "KAY_O": ag_key = "KAY/O"
            
            if ag_key in small_agent_images:
                lbl_img = tk.Label(row, image=small_agent_images[ag_key], bg=r_bg)
                lbl_img.pack(side="left", padx=(4, 6))
            else:
                lbl_ag_txt = tk.Label(row, text=p['agent'][:4], font=("Consolas", 8, "bold"), bg=r_bg, fg="#00F0FF", width=5, anchor="w")
                lbl_ag_txt.pack(side="left", padx=(2, 0))
            
            # 2. Player Name
            tk.Label(row, text=p['name'][:20], font=("Consolas", 9, "bold"), bg=r_bg, fg="#FFFFFF", width=20, anchor="w").pack(side="left", padx=(4, 0))
            
            # 3. Party Badge (Grup)
            p_bg = p['party_color'] if p.get('party_label') != "-" else r_bg
            p_fg = "#000000" if p.get('party_label') != "-" else "#555B6E"
            lbl_party = tk.Label(row, text=p.get('party_label', '-'), font=("Consolas", 8, "bold"), bg=p_bg, fg=p_fg, width=4, relief="flat", padx=2)
            lbl_party.pack(side="left", padx=(4, 4))

            # 4. Account Level
            tk.Label(row, text=str(p['level']), font=("Consolas", 8), bg=r_bg, fg="#A0A5B5", width=5, anchor="w").pack(side="left", padx=(2, 0))
            
            # 5. Current Rank Icon or Text + RR
            rnk_key = p['rank'].upper().replace(" ", "_")
            if rnk_key in rank_images:
                lbl_rnk_img = tk.Label(row, image=rank_images[rnk_key], bg=r_bg)
                lbl_rnk_img.pack(side="left", padx=(2, 4))
            else:
                tk.Label(row, text=p['rank'][:12], font=("Consolas", 8, "bold"), bg=r_bg, fg="#A0A5B5", width=12, anchor="w").pack(side="left", padx=(2, 4))
            
            tk.Label(row, text=p['rr'][:10], font=("Consolas", 8, "bold"), bg=r_bg, fg="#FFDD00", width=10, anchor="w").pack(side="left", padx=(0, 0))
            
            # 6. Peak Rank Icon or Text (Right Aligned)
            peak_key = p['peak'].upper().replace(" ", "_")
            if peak_key in rank_images:
                lbl_peak_img = tk.Label(row, image=rank_images[peak_key], bg=r_bg)
                lbl_peak_img.pack(side="right", padx=(2, 6))
            else:
                tk.Label(row, text=p['peak'][:12], font=("Consolas", 8), bg=r_bg, fg="#B8B8C8", anchor="e", width=12).pack(side="right", padx=6)
            
            player_labels_widgets.append(row)

    render_section("TAKIMIM (MY TEAM)", my_team, "#00F0FF")
    
