def get_masked_title():
    import random
    if sec_title_mask == 0:
        return "Spotify"
    elif sec_title_mask == 1:
        return "Calculator"
    elif sec_title_mask == 2:
        return "Notepad"
    elif sec_title_mask == 3:
        return "Discord"
    else:
        fake_titles = [
            "Application Frame Host", "Runtime Broker", "System Service Host", 
            "NVIDIA Share Overlay", "Realtek Audio Control", "Intel HD Graphics Control Panel",
            "Windows Defender SmartScreen", "Service Host: Local System"
        ]
        return random.choice(fake_titles)

