def hotkey_listener():
    """Arka planda tuş basımlarını dinleyen thread."""
    global menu_visible, trigger_on, color_index, draw_fov_on, sproof_on, fov_size, fire_delay
    global selected_index, overlay_root, trigger_mode, trigger_bind_vk, trigger_bind_name
    global waiting_for_bind, waiting_for_aim_bind, toggle_active, fire_mode, FIRE_KEY_VK, FIRE_KEY_NAME
    global waiting_for_fire_bind, instalock_on, show_agent_on, agent_index, current_tab
    global henrik_api_key, player_region, region_index, humanizer_on, bhop_on, autopistol_on, anti_afk_on, watermark_on, watermark_rainbow, discord_rpc_on, discord_client_id, auto_crouch_on, snap_tap_on, center_dot_on, recoil_assist_on, counter_strafe_on, headshot_priority_on, eco_tracker_on, multi_ms_on
    global sec_bypass_level, sec_title_mask, sec_delay_jitter, sec_scan_jitter
    global aimbot_on, aim_mode, aim_bind_vk, aim_bind_name, aim_fov_size, aim_smooth, aim_headshot, aim_show_fov
    
    prev_ins = False
    prev_up = False
    prev_down = False
    prev_left = False
    prev_right = False
    prev_tab = False
    prev_f5 = False
    prev_f2 = False
    
    while True:
        time.sleep(0.02)
        if not overlay_root:
            continue
        
        if waiting_for_bind:
            excluded_vks = {VK_UP, VK_DOWN, VK_LEFT, VK_RIGHT, VK_INSERT, 0x09}
            for vk in range(1, 256):
                if vk in excluded_vks:
                    continue
                if is_key_pressed(vk):
                    trigger_bind_vk = vk
                    trigger_bind_name = get_vk_name(vk)
                    waiting_for_bind = False
                    save_config()
                    overlay_root.after(0, update_overlay_ui)
                    time.sleep(0.3)
                    break
            continue
        
        if waiting_for_fire_bind:
            excluded_vks = {VK_UP, VK_DOWN, VK_LEFT, VK_RIGHT, VK_INSERT, 0x09}
            for vk in range(1, 256):
                if vk in excluded_vks:
                    continue
                if is_key_pressed(vk):
                    FIRE_KEY_VK = vk
                    FIRE_KEY_NAME = get_vk_name(vk)
                    waiting_for_fire_bind = False
                    save_config()
                    overlay_root.after(0, update_overlay_ui)
                    time.sleep(0.3)
                    break
            continue

        if waiting_for_aim_bind:
            excluded_vks = {VK_UP, VK_DOWN, VK_LEFT, VK_RIGHT, VK_INSERT, 0x09}
            for vk in range(1, 256):
                if vk in excluded_vks:
                    continue
                if is_key_pressed(vk):
                    aim_bind_vk = vk
                    aim_bind_name = get_vk_name(vk)
                    waiting_for_aim_bind = False
                    save_config()
                    overlay_root.after(0, update_overlay_ui)
                    time.sleep(0.3)
                    break
            continue
            
        ins_pressed = is_key_pressed(VK_INSERT)
        if ins_pressed and not prev_ins:
            menu_visible = not menu_visible
            overlay_root.after(0, update_overlay_ui)
        prev_ins = ins_pressed

        f5_pressed = is_key_pressed(VK_F5)
        if f5_pressed and not prev_f5:
            fetch_live_match_data()
            if overlay_root:
                try:
                    overlay_root.after(0, update_overlay_ui)
                except Exception:
                    pass
        prev_f5 = f5_pressed

        f2_pressed = is_key_pressed(0x71)  # VK_F2
        if f2_pressed and not prev_f2:
            instalock_on = not instalock_on
            if instalock_on:
                show_agent_on = False
            save_config()
            print(f"{CYAN}[INSTALOCK] {'AKTIF' if instalock_on else 'KAPALI'} (F2){RESET}")
            if overlay_root:
                try:
                    overlay_root.after(0, update_overlay_ui)
                except Exception:
                    pass
        prev_f2 = f2_pressed

        if menu_visible:
            tab_pressed = is_key_pressed(0x09)
            if tab_pressed and not prev_tab:
                current_tab = (current_tab + 1) % 6
                selected_index = 0
                overlay_root.after(0, update_overlay_ui)
            prev_tab = tab_pressed

            max_items = 12 if current_tab == 0 else (8 if current_tab == 1 else (3 if current_tab == 2 else (2 if current_tab == 3 else (13 if current_tab == 4 else 6))))

            up_pressed = is_key_pressed(VK_UP)
            if up_pressed and not prev_up:
                selected_index = (selected_index - 1) % max_items
                overlay_root.after(0, update_overlay_ui)
            prev_up = up_pressed

            down_pressed = is_key_pressed(VK_DOWN)
            if down_pressed and not prev_down:
                selected_index = (selected_index + 1) % max_items
                overlay_root.after(0, update_overlay_ui)
            prev_down = down_pressed

            left_pressed = is_key_pressed(VK_LEFT)
            right_pressed = is_key_pressed(VK_RIGHT)

            if (left_pressed and not prev_left) or (right_pressed and not prev_right):
                is_right = right_pressed and not prev_right

                if current_tab == 0:  # TRIGGER
                    if selected_index == 0:
                        trigger_on = not trigger_on
                        if not trigger_on:
                            toggle_active = False
                    elif selected_index == 1:
                        color_index = (color_index + (1 if is_right else -1)) % len(color_options)
                    elif selected_index == 2:
                        trigger_mode = "TOGGLE" if trigger_mode == "HOLD" else "HOLD"
                        toggle_active = False
                    elif selected_index == 3:
                        if is_right:
                            waiting_for_bind = True
                        else:
                            trigger_bind_vk = VK_CAPITAL
                            trigger_bind_name = "CAPS LOCK"
                            waiting_for_bind = False
                    elif selected_index == 4:
                        fire_mode = "INTERCEPTION"
                    elif selected_index == 5:
                        if is_right:
                            waiting_for_fire_bind = True
                        else:
                            FIRE_KEY_VK = 0x4B
                            FIRE_KEY_NAME = "K"
                            waiting_for_fire_bind = False
                    elif selected_index == 6:
                        if is_right:
                            fire_delay = min(200, fire_delay + 5)
                        else:
                            fire_delay = max(0, fire_delay - 5)
                    elif selected_index == 7:
                        draw_fov_on = not draw_fov_on
                    elif selected_index == 8:
                        presets = [3, 4, 5, 7, 10, 20, 30, 50, 60, 80, 100, 150, 200, 300]
                        idx = presets.index(fov_size) if fov_size in presets else 0
                        idx = (idx + (1 if is_right else -1)) % len(presets)
                        fov_size = presets[idx]
                    elif selected_index == 9:
                        humanizer_on = not humanizer_on
                    elif selected_index == 10:
                        headshot_priority_on = not headshot_priority_on
                    elif selected_index == 11:
                        multi_ms_on = not multi_ms_on

                elif current_tab == 1:  # AIMBOT
                    if selected_index == 0:
                        aimbot_on = not aimbot_on
                    elif selected_index == 1:
                        aim_mode = "TOGGLE" if aim_mode == "HOLD" else "HOLD"
                    elif selected_index == 2:
                        if is_right:
                            waiting_for_aim_bind = True
                        else:
                            aim_bind_vk = VK_MENU
                            aim_bind_name = "ALT"
                            waiting_for_aim_bind = False
                    elif selected_index == 3:
                        aim_smooth = max(1, min(500, aim_smooth + (25 if is_right else -25)))
                    elif selected_index == 4:
                        aim_headshot = not aim_headshot
                    elif selected_index == 5:
                        aim_show_fov = not aim_show_fov
                    elif selected_index == 6:
                        aim_fov_size = max(20, min(400, aim_fov_size + (10 if is_right else -10)))

                elif current_tab == 2:  # INSTALOCK
                    if selected_index == 0:
                        instalock_on = not instalock_on
                        if instalock_on:
                            show_agent_on = False
                    elif selected_index == 1:
                        show_agent_on = not show_agent_on
                        if show_agent_on:
                            instalock_on = False
                    elif selected_index == 2:
                        agent_index = (agent_index + (1 if is_right else -1)) % len(agent_options)

                elif current_tab == 3:  # OYUNCULAR
                    if selected_index == 0:
                        region_index = (region_index + (1 if is_right else -1)) % len(region_options)
                        player_region = region_options[region_index]
                    elif selected_index == 1:
                        fetch_live_match_data()

                elif current_tab == 4:  # MISC
                    if selected_index == 0:
                        sproof_on = not sproof_on
                    elif selected_index == 1:
                        bhop_on = not bhop_on
                    elif selected_index == 2:
                        autopistol_on = not autopistol_on
                    elif selected_index == 3:
                        anti_afk_on = not anti_afk_on
                    elif selected_index == 4:
                        watermark_on = not watermark_on
                    elif selected_index == 5:
                        watermark_rainbow = not watermark_rainbow
                    elif selected_index == 6:
                        discord_rpc_on = not discord_rpc_on
                    elif selected_index == 7:
                        auto_crouch_on = not auto_crouch_on
                    elif selected_index == 8:
                        snap_tap_on = not snap_tap_on
                    elif selected_index == 9:
                        center_dot_on = not center_dot_on
                    elif selected_index == 10:
                        recoil_assist_on = not recoil_assist_on
                    elif selected_index == 11:
                        counter_strafe_on = not counter_strafe_on
                    elif selected_index == 12:
                        eco_tracker_on = not eco_tracker_on

                elif current_tab == 5:  # SECURITY
                    if selected_index == 2:
                        sec_bypass_level = (sec_bypass_level + (1 if is_right else -1)) % 3
                    elif selected_index == 3:
                        sec_title_mask = (sec_title_mask + (1 if is_right else -1)) % 5
                        if overlay_root:
                            overlay_root.title(get_masked_title())
                    elif selected_index == 4:
                        sec_delay_jitter = (sec_delay_jitter + (1 if is_right else -1)) % 4
                    elif selected_index == 5:
                        sec_scan_jitter = not sec_scan_jitter

                save_config()
                overlay_root.after(0, update_overlay_ui)

            prev_left = left_pressed
            prev_right = right_pressed

